55	 * abstract ProtocolSupport.
56	 */
57	public abstract class AbstractProtocol implements Protocol, ScopeModelAware {
58	
59	    protected final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(getClass());
60	
61	    protected final Map<String, Exporter<?>> exporterMap = new ConcurrentHashMap<>();
62	
63	    /**
64	     * <host:port, ProtocolServer>
65	     */
66	    protected final ConcurrentMap<String, ProtocolServer> serverMap = new ConcurrentHashMap<>();
67	
68	    // TODO SoftReference
69	    protected final Set<Invoker<?>> invokers = new ConcurrentHashSet<>();
70	
71	    protected FrameworkModel frameworkModel;
72	
73	    private final Set<String> optimizers = new ConcurrentHashSet<>();
74	
75	    @Override
76	    public void setFrameworkModel(FrameworkModel frameworkModel) {
77	        this.frameworkModel = frameworkModel;
78	    }
79	
80	    protected static String serviceKey(URL url) {
81	        int port = url.getParameter(Constants.BIND_PORT_KEY, url.getPort());
82	        return serviceKey(port, url.getPath(), url.getVersion(), url.getGroup());
83	    }
84	
85	    protected static String serviceKey(int port, String serviceName, String serviceVersion, String serviceGroup) {
86	        return ProtocolUtils.serviceKey(port, serviceName, serviceVersion, serviceGroup);
87	    }
88	
89	    @Override
90	    public List<ProtocolServer> getServers() {
91	        return Collections.unmodifiableList(new ArrayList<>(serverMap.values()));
92	    }
93	
94	    protected void loadServerProperties(ProtocolServer server) {
95	        // read and hold config before destroy
96	        int serverShutdownTimeout =
97	                ConfigurationUtils.getServerShutdownTimeout(server.getUrl().getScopeModel());
98	        server.getAttributes().put(SHUTDOWN_WAIT_KEY, serverShutdownTimeout);
99	    }
100	
101	    protected int getServerShutdownTimeout(ProtocolServer server) {
102	        return (int) server.getAttributes().getOrDefault(SHUTDOWN_WAIT_KEY, DEFAULT_SERVER_SHUTDOWN_TIMEOUT);
103	    }
104	
105	    @Override
106	    public void destroy() {
107	        for (Invoker<?> invoker : invokers) {
108	            if (invoker != null) {
109	                try {
110	                    if (logger.isInfoEnabled()) {
111	                        logger.info("Destroy reference: " + invoker.getUrl());
112	                    }
113	                    invoker.destroy();
114	                } catch (Throwable t) {
115	                    logger.warn(PROTOCOL_FAILED_DESTROY_INVOKER, "", "", t.getMessage(), t);
116	                }
117	            }
118	        }
119	        invokers.clear();
120	
121	        exporterMap.forEach((key, exporter) -> {
122	            if (exporter != null) {
123	                try {
124	                    if (logger.isInfoEnabled()) {
125	                        logger.info("Unexport service: " + exporter.getInvoker().getUrl());
126	                    }
127	                    exporter.unexport();
128	                } catch (Throwable t) {
129	                    logger.warn(PROTOCOL_FAILED_DESTROY_INVOKER, "", "", t.getMessage(), t);
130	                }
131	            }
132	        });
133	        exporterMap.clear();
134	    }
135	
136	    @Override
137	    public <T> Invoker<T> refer(Class<T> type, URL url) throws RpcException {
138	        return protocolBindingRefer(type, url);
139	    }
140	
141	    @Deprecated
142	    protected abstract <T> Invoker<T> protocolBindingRefer(Class<T> type, URL url) throws RpcException;
143	
144	    public Map<String, Exporter<?>> getExporterMap() {
145	        return exporterMap;
146	    }
147	
148	    public Collection<Exporter<?>> getExporters() {
149	        return Collections.unmodifiableCollection(exporterMap.values());
150	    }
151	
152	    protected void optimizeSerialization(URL url) throws RpcException {
153	        String className = url.getParameter(OPTIMIZER_KEY, "");
154	        if (StringUtils.isEmpty(className) || optimizers.contains(className)) {
155	            return;
156	        }
157	
158	        logger.info("Optimizing the serialization process for Kryo, FST, etc...");
159	
160	        try {
161	            Class clazz = Thread.currentThread().getContextClassLoader().loadClass(className);
162	            if (!SerializationOptimizer.class.isAssignableFrom(clazz)) {
163	                throw new RpcException("The serialization optimizer " + className + " isn't an instance of "
164	                        + SerializationOptimizer.class.getName());
165	            }
166	
167	            SerializationOptimizer optimizer = (SerializationOptimizer) clazz.newInstance();
168	
169	            if (optimizer.getSerializableClasses() == null) {
170	                return;
171	            }
172	
173	            for (Class c : optimizer.getSerializableClasses()) {
174	                SerializableClassRegistry.registerClass(c);
175	            }
176	
177	            optimizers.add(className);
178	
179	        } catch (ClassNotFoundException e) {
180	            throw new RpcException("Cannot find the serialization optimizer class: " + className, e);
181	
182	        } catch (InstantiationException | IllegalAccessException e) {
183	            throw new RpcException("Cannot instantiate the serialization optimizer class: " + className, e);
184	        }
185	    }
186	
187	    protected String getAddr(URL url) {
188	        String bindIp = url.getParameter(org.apache.dubbo.remoting.Constants.BIND_IP_KEY, url.getHost());
189	        if (url.getParameter(ANYHOST_KEY, false)) {
190	            bindIp = ANYHOST_VALUE;
191	        }
192	        return NetUtils.getIpByHost(bindIp) + ":"
193	                + url.getParameter(org.apache.dubbo.remoting.Constants.BIND_PORT_KEY, url.getPort());
194	    }
195	}
