137	    public void connected(Channel channel) throws RemotingException {
138	        ExchangeChannel exchangeChannel = HeaderExchangeChannel.getOrAddChannel(channel);
139	        handler.connected(exchangeChannel);
140	        channel.setAttribute(
141	                Constants.CHANNEL_SHUTDOWN_TIMEOUT_KEY,
142	                ConfigurationUtils.getServerShutdownTimeout(channel.getUrl().getOrDefaultApplicationModel()));
143	    }
144	
145	    @Override
146	    public void disconnected(Channel channel) throws RemotingException {
147	        ExchangeChannel exchangeChannel = HeaderExchangeChannel.getOrAddChannel(channel);
148	        try {
149	            handler.disconnected(exchangeChannel);
150	        } finally {
151	            int shutdownTimeout = 0;
152	            Object timeoutObj = channel.getAttribute(Constants.CHANNEL_SHUTDOWN_TIMEOUT_KEY);
153	            if (timeoutObj instanceof Integer) {
154	                shutdownTimeout = (Integer) timeoutObj;
155	            }
156	            DefaultFuture.closeChannel(channel, ConfigurationUtils.reCalShutdownTime(shutdownTimeout));
157	            HeaderExchangeChannel.removeChannel(channel);
158	        }
159	    }
160	
161	    @Override
162	    public void sent(Channel channel, Object message) throws RemotingException {
163	        Throwable exception = null;
164	        try {
165	            ExchangeChannel exchangeChannel = HeaderExchangeChannel.getOrAddChannel(channel);
166	            handler.sent(exchangeChannel, message);
167	        } catch (Throwable t) {
168	            exception = t;
169	            HeaderExchangeChannel.removeChannelIfDisconnected(channel);
170	        }
171	        if (message instanceof Request) {
172	            Request request = (Request) message;
173	            DefaultFuture.sent(channel, request);
174	        }
175	        if (message instanceof MultiMessage) {
176	            MultiMessage multiMessage = (MultiMessage) message;
177	            for (Object single : multiMessage) {
178	                if (single instanceof Request) {
179	                    DefaultFuture.sent(channel, ((Request) single));
180	                }
181	            }
182	        }
183	        if (exception != null) {
184	            if (exception instanceof RuntimeException) {
185	                throw (RuntimeException) exception;
186	            } else if (exception instanceof RemotingException) {
187	                throw (RemotingException) exception;
188	            } else {
189	                throw new RemotingException(
190	                        channel.getLocalAddress(), channel.getRemoteAddress(), exception.getMessage(), exception);
191	            }
192	        }
193	    }
194	
195	    @Override
196	    public void received(Channel channel, Object message) throws RemotingException {
197	        final ExchangeChannel exchangeChannel = HeaderExchangeChannel.getOrAddChannel(channel);
198	        if (message instanceof Request) {
199	            // handle request.
200	            Request request = (Request) message;
201	            if (request.isEvent()) {
202	                handlerEvent(channel, request);
203	            } else {
204	                if (request.isTwoWay()) {
205	                    handleRequest(exchangeChannel, request);
206	                } else {
207	                    handler.received(exchangeChannel, request.getData());
208	                }
209	            }
210	        } else if (message instanceof Response) {
211	            handleResponse(channel, (Response) message);
212	        } else if (message instanceof String) {
213	            if (isClientSide(channel)) {
214	                Exception e = new Exception("Dubbo client can not supported string message: " + message
215	                        + " in channel: " + channel + ", url: " + channel.getUrl());
216	                logger.error(TRANSPORT_UNSUPPORTED_MESSAGE, "", "", e.getMessage(), e);
217	            } else {
218	                String echo = handler.telnet(channel, (String) message);
219	                if (StringUtils.isNotEmpty(echo)) {
220	                    channel.send(echo);
221	                }
222	            }
223	        } else {
224	            handler.received(exchangeChannel, message);
225	        }
226	    }
227	
228	    @Override
229	    public void caught(Channel channel, Throwable exception) throws RemotingException {
230	        if (exception instanceof ExecutionException) {
231	            ExecutionException e = (ExecutionException) exception;
232	            Object msg = e.getRequest();
233	            if (msg instanceof Request) {
234	                Request req = (Request) msg;
235	                if (req.isTwoWay() && !req.isHeartbeat()) {
236	                    Response res = new Response(req.getId(), req.getVersion());
237	                    res.setStatus(Response.SERVER_ERROR);
238	                    res.setErrorMessage(StringUtils.toString(e));
239	                    channel.send(res);
240	                    return;
241	                }
242	            }
243	        }
244	        ExchangeChannel exchangeChannel = HeaderExchangeChannel.getOrAddChannel(channel);
245	        try {
246	            handler.caught(exchangeChannel, exception);
247	        } finally {
248	            HeaderExchangeChannel.removeChannelIfDisconnected(channel);
249	        }
250	    }
251	
252	    @Override
253	    public ChannelHandler getHandler() {
254	        if (handler instanceof ChannelHandlerDelegate) {
255	            return ((ChannelHandlerDelegate) handler).getHandler();
256	        } else {
257	            return handler;
258	        }
259	    }

