43	public abstract class AbstractServer extends AbstractEndpoint implements RemotingServer {
44	
45	    private Set<ExecutorService> executors = new ConcurrentHashSet<>();
46	    private InetSocketAddress localAddress;
47	    private InetSocketAddress bindAddress;
48	    private int accepts;
49	
50	    private ExecutorRepository executorRepository;
51	
52	    public AbstractServer(URL url, ChannelHandler handler) throws RemotingException {
53	        super(url, handler);
54	        executorRepository = ExecutorRepository.getInstance(url.getOrDefaultApplicationModel());
55	        localAddress = getUrl().toInetSocketAddress();
56	
57	        String bindIp = getUrl().getParameter(Constants.BIND_IP_KEY, getUrl().getHost());
58	        int bindPort = getUrl().getParameter(Constants.BIND_PORT_KEY, getUrl().getPort());
59	        if (url.getParameter(ANYHOST_KEY, false) || NetUtils.isInvalidLocalHost(bindIp)) {
60	            bindIp = ANYHOST_VALUE;
61	        }
62	        bindAddress = new InetSocketAddress(bindIp, bindPort);
63	        this.accepts = url.getParameter(ACCEPTS_KEY, DEFAULT_ACCEPTS);
64	        try {
65	            doOpen();
66	            if (logger.isInfoEnabled()) {
67	                logger.info("[SERVICE_PUBLISH][METADATA_REGISTER] Start "
68	                        + getClass().getSimpleName() + " bind " + getBindAddress() + ", export " + getLocalAddress());
69	            }
70	        } catch (Throwable t) {
71	            throw new RemotingException(
72	                    url.toInetSocketAddress(),
73	                    null,
74	                    "Failed to bind " + getClass().getSimpleName() + " on " + bindAddress + ", cause: "
75	                            + t.getMessage(),
76	                    t);
77	        }
78	        executors.add(
79	                executorRepository.createExecutorIfAbsent(ExecutorUtil.setThreadName(url, SERVER_THREAD_POOL_NAME)));
80	    }
81	
82	    protected abstract void doOpen() throws Throwable;
83	
84	    protected abstract void doClose() throws Throwable;
85	
86	    protected abstract int getChannelsSize();
87	
88	    @Override
89	    public void reset(URL url) {
90	        if (url == null) {
91	            return;
92	        }
93	
94	        try {
95	            if (url.hasParameter(ACCEPTS_KEY)) {
96	                int a = url.getParameter(ACCEPTS_KEY, 0);
97	                if (a > 0) {
98	                    this.accepts = a;
99	                }
100	            }
101	        } catch (Throwable t) {
102	            logger.error(INTERNAL_ERROR, "unknown error in remoting module", "", t.getMessage(), t);
103	        }
104	
105	        ExecutorService executor =
106	                executorRepository.createExecutorIfAbsent(ExecutorUtil.setThreadName(url, SERVER_THREAD_POOL_NAME));
107	        executors.add(executor);
108	        executorRepository.updateThreadpool(url, executor);
109	        super.setUrl(getUrl().addParameters(url.getParameters()));
110	    }
111	
112	    @Override
113	    public void send(Object message, boolean sent) throws RemotingException {
114	        Collection<Channel> channels = getChannels();
115	        for (Channel channel : channels) {
116	            if (channel.isConnected()) {
117	                channel.send(message, sent);
118	            }
119	        }
120	    }
121	
122	    @Override
123	    public void close() {
124	        if (logger.isInfoEnabled()) {
125	            logger.info("Close " + getClass().getSimpleName() + " bind " + getBindAddress() + ", export "
126	                    + getLocalAddress());
127	        }
128	
129	        for (ExecutorService executor : executors) {
130	            ExecutorUtil.shutdownNow(executor, 100);
131	        }
132	
133	        try {
134	            super.close();
135	        } catch (Throwable e) {
136	            logger.warn(INTERNAL_ERROR, "unknown error in remoting module", "", e.getMessage(), e);
137	        }
138	
139	        try {
140	            doClose();
141	        } catch (Throwable e) {
142	            logger.warn(INTERNAL_ERROR, "unknown error in remoting module", "", e.getMessage(), e);
143	        }
144	    }
145	
146	    @Override
147	    public void close(int timeout) {
148	        for (ExecutorService executor : executors) {
149	            ExecutorUtil.gracefulShutdown(executor, timeout);
150	        }
151	        close();
152	    }
153	
154	    @Override
155	    public InetSocketAddress getLocalAddress() {
156	        return localAddress;
157	    }
158	
159	    public InetSocketAddress getBindAddress() {
160	        return bindAddress;
161	    }
162	
163	    public int getAccepts() {
164	        return accepts;
165	    }
166	
167	    @Override
168	    public void connected(Channel ch) throws RemotingException {
169	        // If the server has entered the shutdown process, reject any new connection
170	        if (this.isClosing() || this.isClosed()) {
171	            logger.warn(
172	                    INTERNAL_ERROR,
173	                    "unknown error in remoting module",
174	                    "",
175	                    "Close new channel " + ch
176	                            + ", cause: server is closing or has been closed. For example, receive a new connect request while in shutdown process.");
177	            ch.close();
178	            return;
179	        }
180	
181	        if (accepts > 0 && getChannelsSize() > accepts) {
182	            logger.error(
183	                    INTERNAL_ERROR,
184	                    "unknown error in remoting module",
185	                    "",
186	                    "Close channel " + ch + ", cause: The server " + ch.getLocalAddress()
187	                            + " connections greater than max config " + accepts);
188	            ch.close();
189	            return;
190	        }
191	        super.connected(ch);
192	    }
193	
194	    @Override
195	    public void disconnected(Channel ch) throws RemotingException {
196	        if (getChannelsSize() == 0) {
197	            logger.info(
198	                    "All clients has disconnected from " + ch.getLocalAddress() + ". You can graceful shutdown now.");
199	        }
200	        super.disconnected(ch);
201	    }
202	
203	    @Override
204	    public void fireChannelEvent(ChannelEvent event) {
205	        // Default implementation does nothing.
206	        // Subclasses can override this method to implement protocol-specific event handling.
207	        logger.warn(
208	                INTERNAL_ERROR,
209	                "unknown error in remoting module",
210	                "",
211	                "The fireChannelEvent method is not implemented for "
212	                        + getClass().getName() + ", event: " + event);
213	    }
214	}
