51	public abstract class AbstractClient extends AbstractEndpoint implements Client {
52	
53	    private Lock connectLock;
54	
55	    private final boolean needReconnect;
56	
57	    private final FrameworkModel frameworkModel;
58	
59	    protected volatile ExecutorService executor;
60	
61	    protected volatile ScheduledExecutorService connectivityExecutor;
62	
63	    protected long reconnectDuration;
64	
65	    public AbstractClient(URL url, ChannelHandler handler) throws RemotingException {
66	        super(url, handler);
67	
68	        // initialize connectLock before calling connect()
69	        connectLock = new ReentrantLock();
70	
71	        // set default needReconnect true when channel is not connected
72	        needReconnect = url.getParameter(Constants.SEND_RECONNECT_KEY, true);
73	
74	        frameworkModel = url.getOrDefaultFrameworkModel();
75	
76	        initExecutor(url);
77	
78	        reconnectDuration = getReconnectDuration(url);
79	
80	        try {
81	            doOpen();
82	        } catch (Throwable t) {
83	            close();
84	            throw new RemotingException(
85	                    url.toInetSocketAddress(),
86	                    null,
87	                    "Failed to start " + getClass().getSimpleName() + " " + NetUtils.getLocalAddress()
88	                            + " connect to the server " + getRemoteAddress() + ", cause: " + t.getMessage(),
89	                    t);
90	        }
91	
92	        try {
93	            // connect.
94	            connect();
95	            if (logger.isInfoEnabled()) {
96	                logger.info("Start " + getClass().getSimpleName() + " " + NetUtils.getLocalAddress()
97	                        + " connect to the server " + getRemoteAddress());
98	            }
99	        } catch (RemotingException t) {
100	            // If lazy connect client fails to establish a connection, the client instance will still be created,
101	            // and the reconnection will be initiated by ReconnectTask, so there is no need to throw an exception
102	            if (url.getParameter(LAZY_CONNECT_KEY, false)) {
103	                logger.warn(
104	                        TRANSPORT_FAILED_CONNECT_PROVIDER,
105	                        "",
106	                        "",
107	                        "Failed to start " + getClass().getSimpleName() + " " + NetUtils.getLocalAddress()
108	                                + " connect to the server "
109	                                + getRemoteAddress()
110	                                + " (the connection request is initiated by lazy connect client, ignore and retry later!), cause: "
111	                                + t.getMessage(),
112	                        t);
113	                return;
114	            }
115	
116	            if (url.getParameter(Constants.CHECK_KEY, true)) {
117	                close();
118	                throw t;
119	            } else {
120	                logger.warn(
121	                        TRANSPORT_FAILED_CONNECT_PROVIDER,
122	                        "",
123	                        "",
124	                        "Failed to start " + getClass().getSimpleName() + " " + NetUtils.getLocalAddress()
125	                                + " connect to the server " + getRemoteAddress()
126	                                + " (check == false, ignore and retry later!), cause: " + t.getMessage(),
127	                        t);
128	            }
129	        } catch (Throwable t) {
130	            close();
131	            throw new RemotingException(
132	                    url.toInetSocketAddress(),
133	                    null,
134	                    "Failed to start " + getClass().getSimpleName() + " " + NetUtils.getLocalAddress()
135	                            + " connect to the server " + getRemoteAddress() + ", cause: " + t.getMessage(),
136	                    t);
137	        }
138	    }
139	
140	    protected AbstractClient() {
141	        needReconnect = false;
142	        frameworkModel = null;
143	    }
144	
145	    private void initExecutor(URL url) {
146	        ExecutorRepository executorRepository = ExecutorRepository.getInstance(url.getOrDefaultApplicationModel());
147	
148	        /*
149	         * Consumer's executor is shared globally, provider ip doesn't need to be part of the thread name.
150	         *
151	         * Instance of url is InstanceAddressURL, so addParameter actually adds parameters into ServiceInstance,
152	         * which means params are shared among different services. Since client is shared among services this is currently not a problem.
153	         */
154	        url = url.addParameter(THREAD_NAME_KEY, CLIENT_THREAD_POOL_NAME)
155	                .addParameterIfAbsent(THREADPOOL_KEY, DEFAULT_CLIENT_THREADPOOL);
156	        executor = executorRepository.createExecutorIfAbsent(url);
157	
158	        connectivityExecutor = frameworkModel
159	                .getBeanFactory()
160	                .getBean(FrameworkExecutorRepository.class)
161	                .getConnectivityScheduledExecutor();
162	    }
163	
164	    protected static ChannelHandler wrapChannelHandler(URL url, ChannelHandler handler) {
165	        return ChannelHandlers.wrap(handler, url);
166	    }
167	
168	    public InetSocketAddress getConnectAddress() {
169	        return new InetSocketAddress(NetUtils.filterLocalHost(getUrl().getHost()), getUrl().getPort());
170	    }
171	
172	    @Override
173	    public InetSocketAddress getRemoteAddress() {
174	        Channel channel = getChannel();
175	        if (channel == null) {
176	            return getUrl().toInetSocketAddress();
177	        }
178	        return channel.getRemoteAddress();
179	    }
180	
181	    @Override
182	    public InetSocketAddress getLocalAddress() {
183	        Channel channel = getChannel();
184	        if (channel == null) {
185	            return InetSocketAddress.createUnresolved(NetUtils.getLocalHost(), 0);
186	        }
187	        return channel.getLocalAddress();
188	    }
189	
190	    @Override
191	    public boolean isConnected() {
192	        Channel channel = getChannel();
193	        if (channel == null) {
194	            return false;
195	        }
196	        return channel.isConnected();
197	    }
198	
199	    @Override
200	    public Object getAttribute(String key) {
201	        Channel channel = getChannel();
202	        if (channel == null) {
203	            return null;
204	        }
205	        return channel.getAttribute(key);
206	    }
207	
208	    @Override
209	    public void setAttribute(String key, Object value) {
210	        Channel channel = getChannel();
211	        if (channel == null) {
212	            return;
213	        }
214	        channel.setAttribute(key, value);
215	    }
216	
217	    @Override
218	    public void removeAttribute(String key) {
219	        Channel channel = getChannel();
220	        if (channel == null) {
221	            return;
222	        }
223	        channel.removeAttribute(key);
224	    }
225	
226	    @Override
227	    public boolean hasAttribute(String key) {
228	        Channel channel = getChannel();
229	        if (channel == null) {
230	            return false;
231	        }
232	        return channel.hasAttribute(key);
233	    }
234	
235	    @Override
236	    public void send(Object message, boolean sent) throws RemotingException {
237	        if (needReconnect && !isConnected()) {
238	            connect();
239	        }
240	        Channel channel = getChannel();
241	        // TODO Can the value returned by getChannel() be null? need improvement.
242	        if (channel == null || !channel.isConnected()) {
243	            throw new RemotingException(this, "message can not send, because channel is closed . url:" + getUrl());
244	        }
245	        channel.send(message, sent);
246	    }
247	
248	    protected void connect() throws RemotingException {
249	        connectLock.lock();
250	
251	        try {
252	            if (isConnected()) {
253	                return;
254	            }
255	
256	            if (isClosed() || isClosing()) {
257	                logger.warn(
258	                        TRANSPORT_FAILED_CONNECT_PROVIDER,
259	                        "",
260	                        "",
261	                        "No need to connect to server " + getRemoteAddress() + " from "
262	                                + getClass().getSimpleName() + " " + NetUtils.getLocalHost() + " using dubbo version "
263	                                + Version.getVersion() + ", cause: client status is closed or closing.");
264	                return;
265	            }
266	
267	            doConnect();
268	
269	            if (!isConnected()) {
270	                throw new RemotingException(
271	                        this,
272	                        "Failed to connect to server " + getRemoteAddress() + " from "
273	                                + getClass().getSimpleName() + " "
274	                                + NetUtils.getLocalHost() + " using dubbo version " + Version.getVersion()
275	                                + ", cause: Connect wait timeout: " + getConnectTimeout() + "ms.");
276	
277	            } else {
278	                if (logger.isInfoEnabled()) {
279	                    logger.info("Successfully connect to server " + getRemoteAddress() + " from "
280	                            + getClass().getSimpleName() + " "
281	                            + NetUtils.getLocalHost() + " using dubbo version " + Version.getVersion()
282	                            + ", channel is " + this.getChannel());
283	                }
284	            }
285	
286	        } catch (RemotingException e) {
287	            throw e;
288	
289	        } catch (Throwable e) {
290	            throw new RemotingException(
291	                    this,
292	                    "Failed to connect to server " + getRemoteAddress() + " from "
293	                            + getClass().getSimpleName() + " "
294	                            + NetUtils.getLocalHost() + " using dubbo version " + Version.getVersion()
295	                            + ", cause: " + e.getMessage(),
296	                    e);
297	
298	        } finally {
299	            connectLock.unlock();
300	        }
301	    }
302	
303	    public void disconnect() {
304	        connectLock.lock();
305	        try {
306	            try {
307	                Channel channel = getChannel();
308	                if (channel != null) {
309	                    channel.close();
310	                }
311	            } catch (Throwable e) {
312	                logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
313	            }
314	            try {
315	                doDisConnect();
316	            } catch (Throwable e) {
317	                logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
318	            }
319	        } finally {
320	            connectLock.unlock();
321	        }
322	    }
323	
324	    private long getReconnectDuration(URL url) {
325	        int idleTimeout = getIdleTimeout(url);
326	        long heartbeatTimeoutTick = calculateLeastDuration(idleTimeout);
327	        return calculateReconnectDuration(url, heartbeatTimeoutTick);
328	    }
329	
330	    private long calculateLeastDuration(int time) {
331	        if (time / HEARTBEAT_CHECK_TICK <= 0) {
332	            return LEAST_HEARTBEAT_DURATION;
333	        } else {
334	            return time / HEARTBEAT_CHECK_TICK;
335	        }
336	    }
337	
338	    private long calculateReconnectDuration(URL url, long tick) {
339	        long leastReconnectDuration = url.getParameter(LEAST_RECONNECT_DURATION_KEY, LEAST_RECONNECT_DURATION);
340	        return Math.max(leastReconnectDuration, tick);
341	    }
342	
343	    @Override
344	    public void reconnect() throws RemotingException {
345	        connectLock.lock();
346	        try {
347	            disconnect();
348	            connect();
349	        } finally {
350	            connectLock.unlock();
351	        }
352	    }
353	
354	    @Override
355	    public void close() {
356	        if (isClosed()) {
357	            logger.warn(
358	                    TRANSPORT_FAILED_CONNECT_PROVIDER,
359	                    "",
360	                    "",
361	                    "No need to close connection to server " + getRemoteAddress() + " from "
362	                            + getClass().getSimpleName() + " " + NetUtils.getLocalHost() + " using dubbo version "
363	                            + Version.getVersion() + ", cause: the client status is closed.");
364	            return;
365	        }
366	
367	        connectLock.lock();
368	        try {
369	            if (isClosed()) {
370	                logger.warn(
371	                        TRANSPORT_FAILED_CONNECT_PROVIDER,
372	                        "",
373	                        "",
374	                        "No need to close connection to server " + getRemoteAddress() + " from "
375	                                + getClass().getSimpleName() + " " + NetUtils.getLocalHost() + " using dubbo version "
376	                                + Version.getVersion() + ", cause: the client status is closed.");
377	                return;
378	            }
379	
380	            try {
381	                super.close();
382	            } catch (Throwable e) {
383	                logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
384	            }
385	
386	            try {
387	                disconnect();
388	            } catch (Throwable e) {
389	                logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
390	            }
391	
392	            try {
393	                doClose();
394	            } catch (Throwable e) {
395	                logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
396	            }
397	
398	        } finally {
399	            connectLock.unlock();
400	        }
401	    }
402	
403	    @Override
404	    public void close(int timeout) {
405	        close();
406	    }
407	
408	    @Override
409	    public String toString() {
410	        return getClass().getName() + " [" + getLocalAddress() + " -> " + getRemoteAddress() + "]";
411	    }
412	
413	    /**
414	     * Open client.
415	     */
416	    protected abstract void doOpen() throws Throwable;
417	
418	    /**
419	     * Close client.
420	     */
421	    protected abstract void doClose() throws Throwable;
422	
423	    /**
424	     * Connect to server.
425	     */
426	    protected abstract void doConnect() throws Throwable;
427	
428	    /**
429	     * disConnect to server.
430	     */
431	    protected abstract void doDisConnect() throws Throwable;
432	
433	    /**
434	     * Get the connected channel.
435	     */
436	    protected abstract Channel getChannel();
437	}
