29	import org.apache.dubbo.rpc.cluster.LoadBalance;
30	import org.apache.dubbo.rpc.support.RpcUtils;
31	
32	import java.util.ArrayList;
33	import java.util.HashSet;
34	import java.util.List;
35	import java.util.Set;
36	
37	import static org.apache.dubbo.common.constants.CommonConstants.DEFAULT_RETRIES;
38	import static org.apache.dubbo.common.constants.CommonConstants.RETRIES_KEY;
39	import static org.apache.dubbo.common.constants.LoggerCodeConstants.CLUSTER_FAILED_MULTIPLE_RETRIES;
40	
41	/**
42	 * When invoke fails, log the initial error and retry other invokers (retry n times, which means at most n different invokers will be invoked)
43	 * Note that retry causes latency.
44	 * <p>
45	 * <a href="http://en.wikipedia.org/wiki/Failover">Failover</a>
46	 *
47	 */
48	public class FailoverClusterInvoker<T> extends AbstractClusterInvoker<T> {
49	
50	    private static final ErrorTypeAwareLogger logger =
51	            LoggerFactory.getErrorTypeAwareLogger(FailoverClusterInvoker.class);
52	
53	    public FailoverClusterInvoker(Directory<T> directory) {
54	        super(directory);
55	    }
56	
57	    @Override
58	    @SuppressWarnings({"unchecked", "rawtypes"})
59	    public Result doInvoke(Invocation invocation, final List<Invoker<T>> invokers, LoadBalance loadbalance)
60	            throws RpcException {
61	        List<Invoker<T>> copyInvokers = invokers;
62	        String methodName = RpcUtils.getMethodName(invocation);
63	        int len = calculateInvokeTimes(methodName);
64	        // retry loop.
65	        RpcException le = null; // last exception.
66	        List<Invoker<T>> invoked = new ArrayList<>(copyInvokers.size()); // invoked invokers.
67	        Set<String> providers = new HashSet<>(len);
68	        for (int i = 0; i < len; i++) {
69	            // Reselect before retry to avoid a change of candidate `invokers`.
70	            // NOTE: if `invokers` changed, then `invoked` also lose accuracy.
71	            if (i > 0) {
72	                checkWhetherDestroyed();
73	                copyInvokers = list(invocation);
74	                // check again
75	                checkInvokers(copyInvokers, invocation);
76	            }
77	            Invoker<T> invoker = select(loadbalance, invocation, copyInvokers, invoked);
78	            invoked.add(invoker);
79	            RpcContext.getServiceContext().setInvokers((List) invoked);
80	            boolean success = false;
81	            try {
82	                Result result = invokeWithContext(invoker, invocation);
83	                if (le != null && logger.isWarnEnabled()) {
84	                    logger.warn(
85	                            CLUSTER_FAILED_MULTIPLE_RETRIES,
86	                            "failed to retry do invoke",
87	                            "",
88	                            "Although retry the method " + methodName
89	                                    + " in the service " + getInterface().getName()
90	                                    + " was successful by the provider "
91	                                    + invoker.getUrl().getAddress()
92	                                    + ", but there have been failed providers " + providers
93	                                    + " (" + providers.size() + "/" + copyInvokers.size()
94	                                    + ") from the registry "
95	                                    + directory.getUrl().getAddress()
96	                                    + " on the consumer " + NetUtils.getLocalHost()
97	                                    + " using the dubbo version " + Version.getVersion() + ". Last error is: "
98	                                    + le.getMessage(),
99	                            le);
100	                }
101	                success = true;
102	                return result;
103	            } catch (RpcException e) {
104	                if (e.isBiz()) { // biz exception.
105	                    throw e;
106	                }
107	                le = e;
108	            } catch (Throwable e) {
109	                le = new RpcException(e.getMessage(), e);
110	            } finally {
111	                if (!success) {
112	                    providers.add(invoker.getUrl().getAddress());
113	                }
114	            }
115	        }
116	        throw new RpcException(
117	                le.getCode(),
118	                "Failed to invoke the method "
119	                        + methodName + " in the service " + getInterface().getName()
120	                        + ". Tried " + len + " times of the providers " + providers
121	                        + " (" + providers.size() + "/" + copyInvokers.size()
122	                        + ") from the registry " + directory.getUrl().getAddress()
123	                        + " on the consumer " + NetUtils.getLocalHost() + " using the dubbo version "
124	                        + Version.getVersion() + ". Last error is: "
125	                        + le.getMessage(),
126	                le.getCause() != null ? le.getCause() : le);
127	    }
128	
129	    private int calculateInvokeTimes(String methodName) {
130	        int len = getUrl().getMethodParameter(methodName, RETRIES_KEY, DEFAULT_RETRIES) + 1;
131	        RpcContext rpcContext = RpcContext.getClientAttachment();
132	        Object retry = rpcContext.getObjectAttachment(RETRIES_KEY);
133	        if (retry instanceof Number) {
134	            len = ((Number) retry).intValue() + 1;
135	            rpcContext.removeAttachment(RETRIES_KEY);
136	        }
137	        if (len <= 0) {
138	            len = 1;
139	        }
140	
141	        return len;
142	    }
143	}
