31	import org.apache.dubbo.remoting.Constants;
32	import org.apache.dubbo.remoting.RemotingException;
33	import org.apache.dubbo.remoting.RemotingServer;
34	import org.apache.dubbo.remoting.event.ReadOnlyEvent;
35	import org.apache.dubbo.remoting.event.WriteableEvent;
36	import org.apache.dubbo.remoting.exchange.ExchangeChannel;
37	import org.apache.dubbo.remoting.exchange.ExchangeServer;
38	import org.apache.dubbo.remoting.exchange.Request;
39	
40	import java.net.InetSocketAddress;
41	import java.nio.channels.ClosedChannelException;
42	import java.util.ArrayList;
43	import java.util.Collection;
44	import java.util.concurrent.TimeUnit;
45	import java.util.concurrent.atomic.AtomicBoolean;
46	
47	import static java.util.Collections.unmodifiableCollection;
48	import static org.apache.dubbo.common.constants.CommonConstants.READONLY_EVENT;
49	import static org.apache.dubbo.common.constants.CommonConstants.WRITEABLE_EVENT;
50	import static org.apache.dubbo.common.constants.LoggerCodeConstants.INTERNAL_ERROR;
51	import static org.apache.dubbo.common.constants.LoggerCodeConstants.TRANSPORT_FAILED_CLOSE;
52	import static org.apache.dubbo.common.constants.LoggerCodeConstants.TRANSPORT_FAILED_RESPONSE;
53	import static org.apache.dubbo.remoting.Constants.HEARTBEAT_CHECK_TICK;
54	import static org.apache.dubbo.remoting.Constants.LEAST_HEARTBEAT_DURATION;
55	import static org.apache.dubbo.remoting.Constants.TICKS_PER_WHEEL;
56	import static org.apache.dubbo.remoting.utils.UrlUtils.getCloseTimeout;
57	
58	/**
59	 * ExchangeServerImpl
60	 */
61	public class HeaderExchangeServer implements ExchangeServer {
62	
63	    protected final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(getClass());
64	
65	    private final RemotingServer server;
66	
67	    private final AtomicBoolean closed = new AtomicBoolean(false);
68	
69	    public static GlobalResourceInitializer<HashedWheelTimer> IDLE_CHECK_TIMER = new GlobalResourceInitializer<>(
70	            () -> new HashedWheelTimer(
71	                    new NamedThreadFactory("dubbo-server-idleCheck", true), 1, TimeUnit.SECONDS, TICKS_PER_WHEEL),
72	            HashedWheelTimer::stop);
73	
74	    private CloseTimerTask closeTimer;
75	
76	    public HeaderExchangeServer(RemotingServer server) {
77	        Assert.notNull(server, "server == null");
78	        this.server = server;
79	        startIdleCheckTask(getUrl());
80	    }
81	
82	    public RemotingServer getServer() {
83	        return server;
84	    }
85	
86	    @Override
87	    public boolean isClosed() {
88	        return server.isClosed();
89	    }
90	
91	    private boolean isRunning() {
92	        // If there are any client connections,
93	        // our server should be running.
94	        return getChannels().stream().anyMatch(Channel::isConnected);
95	    }
96	
97	    @Override
98	    public void close() {
99	        if (!closed.compareAndSet(false, true)) {
100	            return;
101	        }
102	        doClose();
103	        server.close();
104	    }
105	
106	    @Override
107	    public void close(final int timeout) {
108	        if (!closed.compareAndSet(false, true)) {
109	            return;
110	        }
111	        startClose();
112	        if (timeout > 0) {
113	            final long start = System.currentTimeMillis();
114	            if (getUrl().getParameter(Constants.CHANNEL_SEND_READONLYEVENT_KEY, true)) {
115	                sendChannelEvent(READONLY_EVENT);
116	            }
117	            while (HeaderExchangeServer.this.isRunning() && System.currentTimeMillis() - start < (long) timeout) {
118	                try {
119	                    Thread.sleep(10);
120	                } catch (InterruptedException e) {
121	                    logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
122	                }
123	            }
124	        }
125	        doClose();
126	        server.close(timeout);
127	    }
128	
129	    @Override
130	    public void startClose() {
131	        server.startClose();
132	    }
133	
134	    private void sendChannelEvent(String event) {
135	        Request request = new Request();
136	        request.setEvent(event);
137	        request.setTwoWay(false);
138	        request.setVersion(Version.getProtocolVersion());
139	
140	        Collection<Channel> channels = getChannels();
141	        for (Channel channel : channels) {
142	            try {
143	                if (channel.isConnected()) {
144	                    channel.send(request, getUrl().getParameter(Constants.CHANNEL_READONLYEVENT_SENT_KEY, true));
145	                }
146	            } catch (RemotingException e) {
147	                if (closed.get() && e.getCause() instanceof ClosedChannelException) {
148	                    // ignore ClosedChannelException which means the connection has been closed.
149	                    continue;
150	                }
151	                logger.warn(TRANSPORT_FAILED_RESPONSE, "", "", "send cannot write message error.", e);
152	            }
153	        }
154	    }
155	
156	    private void doClose() {
157	        cancelCloseTask();
158	    }
159	
160	    private void cancelCloseTask() {
161	        if (closeTimer != null) {
162	            closeTimer.cancel();
163	        }
164	    }
165	
166	    @Override
167	    public Collection<ExchangeChannel> getExchangeChannels() {
168	        Collection<ExchangeChannel> exchangeChannels = new ArrayList<>();
169	        Collection<Channel> channels = server.getChannels();
170	        if (CollectionUtils.isNotEmpty(channels)) {
171	            for (Channel channel : channels) {
172	                exchangeChannels.add(HeaderExchangeChannel.getOrAddChannel(channel));
173	            }
174	        }
175	        return exchangeChannels;
176	    }
177	
178	    @Override
179	    public ExchangeChannel getExchangeChannel(InetSocketAddress remoteAddress) {
180	        Channel channel = server.getChannel(remoteAddress);
181	        return HeaderExchangeChannel.getOrAddChannel(channel);
182	    }
183	
184	    @Override
185	    @SuppressWarnings({"unchecked", "rawtypes"})
186	    public Collection<Channel> getChannels() {
187	        return (Collection) getExchangeChannels();
188	    }
189	
190	    @Override
191	    public Channel getChannel(InetSocketAddress remoteAddress) {
192	        return getExchangeChannel(remoteAddress);
193	    }
194	
195	    @Override
196	    public boolean isBound() {
197	        return server.isBound();
198	    }
199	
200	    @Override
201	    public InetSocketAddress getLocalAddress() {
202	        return server.getLocalAddress();
203	    }
204	
205	    @Override
206	    public URL getUrl() {
207	        return server.getUrl();
208	    }
209	
210	    @Override
211	    public ChannelHandler getChannelHandler() {
212	        return server.getChannelHandler();
213	    }
214	
215	    @Override
216	    public void reset(URL url) {
217	        server.reset(url);
218	        try {
219	            int currCloseTimeout = getCloseTimeout(getUrl());
220	            int closeTimeout = getCloseTimeout(url);
221	            if (closeTimeout != currCloseTimeout) {
222	                cancelCloseTask();
223	                startIdleCheckTask(url);
224	            }
225	        } catch (Throwable t) {
226	            logger.error(INTERNAL_ERROR, "unknown error in remoting module", "", t.getMessage(), t);
227	        }
228	    }
229	
230	    @Override
231	    @Deprecated
232	    public void reset(org.apache.dubbo.common.Parameters parameters) {
233	        reset(getUrl().addParameters(parameters.getParameters()));
234	    }
235	
236	    @Override
237	    public void send(Object message) throws RemotingException {
238	        if (closed.get()) {
239	            throw new RemotingException(
240	                    this.getLocalAddress(),
241	                    null,
242	                    "Failed to send message " + message + ", cause: The server " + getLocalAddress() + " is closed!");
243	        }
244	        server.send(message);
245	    }
246	
247	    @Override
248	    public void send(Object message, boolean sent) throws RemotingException {
249	        if (closed.get()) {
250	            throw new RemotingException(
251	                    this.getLocalAddress(),
252	                    null,
253	                    "Failed to send message " + message + ", cause: The server " + getLocalAddress() + " is closed!");
254	        }
255	        server.send(message, sent);
256	    }
257	
258	    /**
259	     * Each interval cannot be less than 1000ms.
260	     */
261	    private long calculateLeastDuration(int time) {
262	        if (time / HEARTBEAT_CHECK_TICK <= 0) {
263	            return LEAST_HEARTBEAT_DURATION;
264	        } else {
265	            return time / HEARTBEAT_CHECK_TICK;
266	        }
267	    }
268	
269	    private void startIdleCheckTask(URL url) {
270	        if (!server.canHandleIdle()) {
271	            AbstractTimerTask.ChannelProvider cp =
272	                    () -> unmodifiableCollection(HeaderExchangeServer.this.getChannels());
273	            int closeTimeout = getCloseTimeout(url);
274	            long closeTimeoutTick = calculateLeastDuration(closeTimeout);
275	            this.closeTimer = new CloseTimerTask(cp, IDLE_CHECK_TIMER.get(), closeTimeoutTick, closeTimeout);
276	        }
277	    }
278	
279	    @Override
280	    public void fireChannelEvent(ChannelEvent event) {
281	        if (event instanceof ReadOnlyEvent) {
282	            sendChannelEvent(READONLY_EVENT);
283	        } else if (event instanceof WriteableEvent) {
284	            sendChannelEvent(WRITEABLE_EVENT);
285	        } else {
286	            // For other events, delegate to the underlying server
287	            server.fireChannelEvent(event);
288	        }
289	    }
290	}
