46	/**
47	 * DefaultMessageClient
48	 */
49	public class HeaderExchangeClient implements ExchangeClient {
50	
51	    private final Client client;
52	    private final ExchangeChannel channel;
53	
54	    public static GlobalResourceInitializer<HashedWheelTimer> IDLE_CHECK_TIMER = new GlobalResourceInitializer<>(
55	            () -> new HashedWheelTimer(
56	                    new NamedThreadFactory("dubbo-client-heartbeat-reconnect", true),
57	                    1,
58	                    TimeUnit.SECONDS,
59	                    TICKS_PER_WHEEL),
60	            HashedWheelTimer::stop);
61	
62	    private ReconnectTimerTask reconnectTimerTask;
63	    private HeartbeatTimerTask heartBeatTimerTask;
64	    private final int idleTimeout;
65	
66	    public HeaderExchangeClient(Client client, boolean startTimer) {
67	        Assert.notNull(client, "Client can't be null");
68	        this.client = client;
69	        this.channel = new HeaderExchangeChannel(client);
70	
71	        if (startTimer) {
72	            URL url = client.getUrl();
73	            idleTimeout = getIdleTimeout(url);
74	            startReconnectTask(url);
75	            startHeartBeatTask(url);
76	        } else {
77	            idleTimeout = 0;
78	        }
79	    }
80	
81	    @Override
82	    public CompletableFuture<Object> request(Object request) throws RemotingException {
83	        return channel.request(request);
84	    }
85	
86	    @Override
87	    public URL getUrl() {
88	        return channel.getUrl();
89	    }
90	
91	    @Override
92	    public InetSocketAddress getRemoteAddress() {
93	        return channel.getRemoteAddress();
94	    }
95	
96	    @Override
97	    public CompletableFuture<Object> request(Object request, int timeout) throws RemotingException {
98	        return channel.request(request, timeout);
99	    }
100	
101	    @Override
102	    public CompletableFuture<Object> request(Object request, ExecutorService executor) throws RemotingException {
103	        return channel.request(request, executor);
104	    }
105	
106	    @Override
107	    public CompletableFuture<Object> request(Object request, int timeout, ExecutorService executor)
108	            throws RemotingException {
109	        return channel.request(request, timeout, executor);
110	    }
111	
112	    @Override
113	    public ChannelHandler getChannelHandler() {
114	        return channel.getChannelHandler();
115	    }
116	
117	    @Override
118	    public boolean isConnected() {
119	        if (channel.isConnected()) {
120	            if (idleTimeout <= 0) {
121	                return true;
122	            }
123	            Long lastRead = (Long) channel.getAttribute(HeartbeatHandler.KEY_READ_TIMESTAMP);
124	            Long now = System.currentTimeMillis();
125	
126	            return lastRead == null || now - lastRead < idleTimeout;
127	        }
128	        return false;
129	    }
130	
131	    @Override
132	    public InetSocketAddress getLocalAddress() {
133	        return channel.getLocalAddress();
134	    }
135	
136	    @Override
137	    public ExchangeHandler getExchangeHandler() {
138	        return channel.getExchangeHandler();
139	    }
140	
141	    @Override
142	    public void send(Object message) throws RemotingException {
143	        channel.send(message);
144	    }
145	
146	    @Override
147	    public void send(Object message, boolean sent) throws RemotingException {
148	        channel.send(message, sent);
149	    }
150	
151	    @Override
152	    public boolean isClosed() {
153	        return channel.isClosed();
154	    }
155	
156	    @Override
157	    public synchronized void close() {
158	        doClose();
159	        channel.close();
160	    }
161	
162	    @Override
163	    public void close(int timeout) {
164	        // Mark the client into the closure process
165	        startClose();
166	        doClose();
167	        channel.close(timeout);
168	    }
169	
170	    @Override
171	    public void startClose() {
172	        channel.startClose();
173	    }
174	
175	    @Override
176	    public void reset(URL url) {
177	        client.reset(url);
178	        // FIXME, should cancel and restart timer tasks if parameters in the new URL are different?
179	    }
180	
181	    @Override
182	    @Deprecated
183	    public void reset(org.apache.dubbo.common.Parameters parameters) {
184	        reset(getUrl().addParameters(parameters.getParameters()));
185	    }
186	
187	    @Override
188	    public synchronized void reconnect() throws RemotingException {
189	        client.reconnect();
190	    }
191	
192	    @Override
193	    public Object getAttribute(String key) {
194	        return channel.getAttribute(key);
195	    }
196	
197	    @Override
198	    public void setAttribute(String key, Object value) {
199	        channel.setAttribute(key, value);
200	    }
201	
202	    @Override
203	    public void removeAttribute(String key) {
204	        channel.removeAttribute(key);
205	    }
206	
207	    @Override
208	    public boolean hasAttribute(String key) {
209	        return channel.hasAttribute(key);
210	    }
211	
212	    private void startHeartBeatTask(URL url) {
213	        if (!client.canHandleIdle()) {
214	            int heartbeat = getHeartbeat(url);
215	            long heartbeatTick = calculateLeastDuration(heartbeat);
216	            heartBeatTimerTask = new HeartbeatTimerTask(
217	                    () -> Collections.singleton(this), IDLE_CHECK_TIMER.get(), heartbeatTick, heartbeat);
218	        }
219	    }
220	
221	    private void startReconnectTask(URL url) {
222	        if (shouldReconnect(url)) {
223	            long heartbeatTimeoutTick = calculateLeastDuration(idleTimeout);
224	            reconnectTimerTask = new ReconnectTimerTask(
225	                    () -> Collections.singleton(this),
226	                    IDLE_CHECK_TIMER.get(),
227	                    calculateReconnectDuration(url, heartbeatTimeoutTick),
228	                    idleTimeout);
229	        }
230	    }
231	
232	    private void doClose() {
233	        if (heartBeatTimerTask != null) {
234	            heartBeatTimerTask.cancel();
235	            heartBeatTimerTask = null;
236	        }
237	        if (reconnectTimerTask != null) {
238	            reconnectTimerTask.cancel();
239	            reconnectTimerTask = null;
240	        }
241	    }
242	
243	    /**
244	     * Each interval cannot be less than 1000ms.
245	     */
246	    private long calculateLeastDuration(int time) {
247	        if (time / HEARTBEAT_CHECK_TICK <= 0) {
248	            return LEAST_HEARTBEAT_DURATION;
249	        } else {
250	            return time / HEARTBEAT_CHECK_TICK;
251	        }
252	    }
253	
254	    private long calculateReconnectDuration(URL url, long tick) {
255	        long leastReconnectDuration = url.getParameter(LEAST_RECONNECT_DURATION_KEY, LEAST_RECONNECT_DURATION);
256	        return Math.max(leastReconnectDuration, tick);
257	    }
258	
259	    protected boolean shouldReconnect(URL url) {
260	        return !Boolean.FALSE.toString().equalsIgnoreCase(url.getParameter(Constants.RECONNECT_KEY));
261	    }
262	
263	    @Override
264	    public String toString() {
265	        return "HeaderExchangeClient [channel=" + channel + "]";
266	    }
267	}
