37	public class UrlUtils {
38	    private static final String ALLOWED_SERIALIZATION_KEY = "allowedSerialization";
39	
40	    public static int getCloseTimeout(URL url) {
41	        String configuredCloseTimeout = SystemPropertyConfigUtils.getSystemProperty(
42	                CommonConstants.DubboProperty.DUBBO_CLOSE_TIMEOUT_CONFIG_KEY);
43	        int defaultCloseTimeout = -1;
44	        if (StringUtils.isNotEmpty(configuredCloseTimeout)) {
45	            try {
46	                defaultCloseTimeout = Integer.parseInt(configuredCloseTimeout);
47	            } catch (NumberFormatException e) {
48	                // use default heartbeat
49	            }
50	        }
51	        if (defaultCloseTimeout < 0) {
52	            defaultCloseTimeout = getIdleTimeout(url);
53	        }
54	        int closeTimeout = url.getParameter(Constants.CLOSE_TIMEOUT_KEY, defaultCloseTimeout);
55	        int heartbeat = getHeartbeat(url);
56	        if (closeTimeout < heartbeat * 2) {
57	            throw new IllegalStateException("closeTimeout < heartbeatInterval * 2");
58	        }
59	        return closeTimeout;
60	    }
61	
62	    public static int getIdleTimeout(URL url) {
63	        int heartBeat = getHeartbeat(url);
64	        // idleTimeout should be at least more than twice heartBeat because possible retries of client.
65	        int idleTimeout = url.getParameter(Constants.HEARTBEAT_TIMEOUT_KEY, heartBeat * 3);
66	        if (idleTimeout < heartBeat * 2) {
67	            throw new IllegalStateException("idleTimeout < heartbeatInterval * 2");
68	        }
69	        return idleTimeout;
70	    }
71	
72	    public static int getHeartbeat(URL url) {
73	        String configuredHeartbeat =
74	                SystemPropertyConfigUtils.getSystemProperty(CommonConstants.DubboProperty.DUBBO_HEARTBEAT_CONFIG_KEY);
75	        int defaultHeartbeat = Constants.DEFAULT_HEARTBEAT;
76	        if (StringUtils.isNotEmpty(configuredHeartbeat)) {
77	            try {
78	                defaultHeartbeat = Integer.parseInt(configuredHeartbeat);
79	            } catch (NumberFormatException e) {
80	                // use default heartbeat
81	            }
82	        }
83	        return url.getParameter(Constants.HEARTBEAT_KEY, defaultHeartbeat);
84	    }
85	
86	    /**
87	     * Get the serialization id
88	     *
89	     * @param url url
90	     * @return {@link Byte}
91	     */
92	    public static Byte serializationId(URL url) {
93	        Byte serializationId;
94	        // Obtain the value from prefer_serialization. Such as.fastjson2,hessian2
95	        List<String> preferSerials = preferSerialization(url);
96	        for (String preferSerial : preferSerials) {
97	            if ((serializationId = CodecSupport.getIDByName(preferSerial)) != null) {
98	                return serializationId;
99	            }
100	        }
101	
102	        // Secondly, obtain the value from serialization
103	        if ((serializationId = CodecSupport.getIDByName(url.getParameter(SERIALIZATION_KEY))) != null) {
104	            return serializationId;
105	        }
106	
107	        // Finally, use the default serialization type
108	        return CodecSupport.getIDByName(DefaultSerializationSelector.getDefaultRemotingSerialization());
109	    }
110	
111	    /**
112	     * Get the serialization or default serialization
113	     *
114	     * @param url url
115	     * @return {@link String}
116	     */
117	    public static String serializationOrDefault(URL url) {
118	        // noinspection OptionalGetWithoutIsPresent
119	        Optional<String> serializations = allSerializations(url).stream().findFirst();
120	        return serializations.orElseGet(DefaultSerializationSelector::getDefaultRemotingSerialization);
121	    }
122	
123	    /**
124	     * Get the all serializations,ensure insertion order
125	     *
126	     * @param url url
127	     * @return {@link List}<{@link String}>
128	     */
129	    @SuppressWarnings("unchecked")
130	    public static Collection<String> allSerializations(URL url) {
131	        // preferSerialization -> serialization -> default serialization
132	        Set<String> serializations = new LinkedHashSet<>(preferSerialization(url));
133	        Optional.ofNullable(url.getParameter(SERIALIZATION_KEY))
134	                .filter(StringUtils::isNotBlank)
135	                .ifPresent(serializations::add);
136	        serializations.add(DefaultSerializationSelector.getDefaultRemotingSerialization());
137	        return Collections.unmodifiableSet(serializations);
138	    }
139	
140	    /**
141	     * Prefer Serialization
142	     *
143	     * @param url url
144	     * @return {@link List}<{@link String}>
145	     */
146	    public static List<String> preferSerialization(URL url) {
147	        String preferSerialization = url.getParameter(PREFER_SERIALIZATION_KEY);
148	        if (StringUtils.isNotBlank(preferSerialization)) {
149	            return Collections.unmodifiableList(StringUtils.splitToList(preferSerialization, ','));
150	        }
151	        return Collections.emptyList();
152	    }
153	}
