69	        io.netty.channel.ChannelHandler codec = Http3Helper.configCodec(Http3.newQuicClientCodecBuilder(), getUrl())
70	                .sslContext(Http3SslContexts.buildClientSslContext(getUrl()))
71	                .build();
72	        io.netty.channel.Channel nettyDatagramChannel = new Bootstrap()
73	                .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, getConnectTimeout())
74	                .group(NettyEventLoopFactory.NIO_EVENT_LOOP_GROUP.get())
75	                .channel(NioDatagramChannel.class)
76	                .handler(new ChannelInitializer<NioDatagramChannel>() {
77	                    @Override
78	                    protected void initChannel(NioDatagramChannel ch) {
79	                        ch.pipeline().addLast(codec);
80	                    }
81	                })
82	                .bind(0)
83	                .sync()
84	                .channel();
85	        datagramChannel.set(nettyDatagramChannel);
86	        nettyDatagramChannel.closeFuture().addListener(channelFuture -> datagramChannel.set(null));
87	
88	        NettyConnectionHandler connectionHandler = new NettyConnectionHandler(this);
89	        bootstrap = QuicChannel.newBootstrap(nettyDatagramChannel)
90	                .handler(new ChannelInitializer<QuicChannel>() {
91	                    @Override
92	                    protected void initChannel(QuicChannel ch) {
93	                        ChannelPipeline pipeline = ch.pipeline();
94	                        pipeline.addLast(new Http3ClientConnectionHandler());
95	                        pipeline.addLast(Constants.CONNECTION_HANDLER_NAME, connectionHandler);
96	                        pipelineConfigurator.accept(pipeline);
97	                        ch.closeFuture().addListener(channelFuture -> clearNettyChannel());
98	                    }
99	                })
100	                .remoteAddress(getConnectAddress());
101	    }
102	
103	    @Override
104	    protected ChannelFuture performConnect() {
105	        Channel channel = getNettyDatagramChannel();
106	        if (channel == null) {
107	            return null;
108	        }
109	        ChannelPromise promise = channel.newPromise();
110	        GenericFutureListener<Future<QuicChannel>> listener = f -> {
111	            if (f.isSuccess()) {
112	                promise.setSuccess(null);
113	            } else {
114	                promise.setFailure(f.cause());
115	            }
116	        };
117	        bootstrap.connect().addListener(listener);
118	        return promise;
119	    }
120	
121	    /**
122	     * Override this method to preserve the configured loopback address.
123	     * The superclass implementation may rewrite it to a non-loopback local IP,
124	     * potentially causing a peer-address mismatch on multi-homed hosts.
125	     * QUIC requires the peer's IP address to remain stable until the handshake
126	     * is confirmed.
127	     */
128	    @Override
129	    public InetSocketAddress getConnectAddress() {
130	        String host = getUrl().getHost();
131	        if (NetUtils.isLocalHost(host)) {
132	            return getUrl().toInetSocketAddress();
133	        }
134	        return super.getConnectAddress();
135	    }
136	
137	    @Override
138	    protected void performClose() {
139	        super.performClose();
140	        io.netty.channel.Channel current = getNettyDatagramChannel();
141	        if (current != null) {
142	            current.close();
143	        }
144	        datagramChannel.set(null);
145	    }
146	
147	    private io.netty.channel.Channel getNettyDatagramChannel() {
148	        return datagramChannel.get();
149	    }
150	}
