104	            Invocation invocation,
105	            boolean needToPrintMessage,
106	            Holder<RouterSnapshotNode<T>> nodeHolder,
107	            Holder<String> messageHolder)
108	            throws RpcException {
109	        if (CollectionUtils.isEmpty(invokers)
110	                || (conditionRouters.size() == 0 && multiDestConditionRouters.size() == 0)) {
111	            if (needToPrintMessage) {
112	                messageHolder.set(
113	                        "Directly return. Reason: Invokers from previous router is empty or conditionRouters is empty.");
114	            }
115	            return invokers;
116	        }
117	
118	        // We will check enabled status inside each router.
119	        StringBuilder resultMessage = null;
120	        if (needToPrintMessage) {
121	            resultMessage = new StringBuilder();
122	        }
123	
124	        List<? extends AbstractStateRouter<T>> routers;
125	        if (routerRule instanceof MultiDestConditionRouterRule) {
126	            routers = multiDestConditionRouters;
127	        } else {
128	            routers = conditionRouters;
129	        }
130	
131	        for (AbstractStateRouter<T> router : routers) {
132	            invokers = router.route(invokers, url, invocation, needToPrintMessage, nodeHolder);
133	            if (needToPrintMessage) {
134	                resultMessage.append(messageHolder.get());
135	            }
136	        }
137	
138	        if (needToPrintMessage) {
139	            messageHolder.set(resultMessage.toString());
140	        }
141	
142	        return invokers;
143	    }
144	
145	    @Override
146	    public boolean isForce() {
147	        return (routerRule != null && routerRule.isForce());
148	    }
149	
150	    private void generateConditions(AbstractRouterRule rule) {
151	        if (rule == null || !rule.isValid()) {
152	            return;
153	        }
154	
155	        if (rule instanceof ConditionRouterRule) {
156	            this.conditionRouters = ((ConditionRouterRule) rule)
157	                    .getConditions().stream()
158	                            .map(condition ->
159	                                    new ConditionStateRouter<T>(getUrl(), condition, rule.isForce(), rule.isEnabled()))
160	                            .collect(Collectors.toList());
161	
162	            for (ConditionStateRouter<T> conditionRouter : this.conditionRouters) {
163	                conditionRouter.setNextRouter(TailStateRouter.getInstance());
164	            }
165	        } else if (rule instanceof MultiDestConditionRouterRule) {
166	            this.multiDestConditionRouters = ((MultiDestConditionRouterRule) rule)
167	                    .getConditions().stream()
168	                            .map(condition -> new MultiDestConditionRouter<T>(
169	                                    getUrl(), condition, rule.isForce(), rule.isEnabled()))
170	                            .collect(Collectors.toList());
171	
172	            for (MultiDestConditionRouter<T> conditionRouter : this.multiDestConditionRouters) {
173	                conditionRouter.setNextRouter(TailStateRouter.getInstance());
174	            }
175	        }
176	    }
