133	                ch.pipeline() // .addLast("logging",new LoggingHandler(LogLevel.INFO))//for debug
134	                        .addLast("decoder", adapter.getDecoder())
135	                        .addLast("encoder", adapter.getEncoder())
136	                        .addLast("client-idle-handler", new IdleStateHandler(heartbeatInterval, 0, 0, MILLISECONDS))
137	                        .addLast("handler", nettyClientHandler);
138	
139	                String socksProxyHost =
140	                        ConfigurationUtils.getProperty(getUrl().getOrDefaultApplicationModel(), SOCKS_PROXY_HOST);
141	                if (socksProxyHost != null && !isFilteredAddress(getUrl().getHost())) {
142	                    int socksProxyPort = Integer.parseInt(ConfigurationUtils.getProperty(
143	                            getUrl().getOrDefaultApplicationModel(), SOCKS_PROXY_PORT, DEFAULT_SOCKS_PROXY_PORT));
144	                    Socks5ProxyHandler socks5ProxyHandler =
145	                            new Socks5ProxyHandler(new InetSocketAddress(socksProxyHost, socksProxyPort));
146	                    ch.pipeline().addFirst(socks5ProxyHandler);
