184	    private void doConnect(InetSocketAddress serverAddress) throws RemotingException {
185	        long start = System.currentTimeMillis();
186	        ChannelFuture future = bootstrap.connect(serverAddress);
187	        try {
188	            boolean ret = future.awaitUninterruptibly(getConnectTimeout(), MILLISECONDS);
189	
190	            if (ret && future.isSuccess()) {
191	                Channel newChannel = future.channel();
192	                try {
193	                    // Close old channel
194	                    // copy reference
195	                    Channel oldChannel = NettyClient.this.channel;
196	                    if (oldChannel != null) {
197	                        try {
198	                            if (logger.isInfoEnabled()) {
199	                                logger.info("Close old netty channel " + oldChannel + " on create new netty channel "
200	                                        + newChannel);
201	                            }
202	                            oldChannel.close();
203	                        } finally {
204	                            NettyChannel.removeChannelIfDisconnected(oldChannel);
205	                        }
206	                    }
207	                } finally {
208	                    if (NettyClient.this.isClosed()) {
209	                        try {
210	                            if (logger.isInfoEnabled()) {
211	                                logger.info("Close new netty channel " + newChannel + ", because the client closed.");
212	                            }
213	                            newChannel.close();
214	                        } finally {
215	                            NettyClient.this.channel = null;
216	                            NettyChannel.removeChannelIfDisconnected(newChannel);
217	                        }
218	                    } else {
219	                        NettyClient.this.channel = newChannel;
220	                    }
221	                }
222	            } else if (future.cause() != null) {
223	
224	                Throwable cause = future.cause();
225	
226	                // 6-1 Failed to connect to provider server by other reason.
227	
228	                RemotingException remotingException = new RemotingException(
229	                        this,
230	                        "client(url: " + getUrl() + ") failed to connect to server " + serverAddress
231	                                + ", error message is:" + cause.getMessage(),
232	                        cause);
233	
234	                logger.error(
235	                        TRANSPORT_FAILED_CONNECT_PROVIDER,
236	                        "network disconnected",
237	                        "",
238	                        "Failed to connect to provider server by other reason.",
239	                        cause);
240	
241	                throw remotingException;
242	
243	            } else {
244	
245	                // 6-2 Client-side timeout
246	
247	                RemotingException remotingException = new RemotingException(
248	                        this,
249	                        "client(url: " + getUrl() + ") failed to connect to server "
250	                                + serverAddress + " client-side timeout "
251	                                + getConnectTimeout() + "ms (elapsed: " + (System.currentTimeMillis() - start)
252	                                + "ms) from netty client "
253	                                + NetUtils.getLocalHost() + " using dubbo version " + Version.getVersion());
254	
255	                logger.error(
256	                        TRANSPORT_CLIENT_CONNECT_TIMEOUT,
257	                        "provider crash",
258	                        "",
259	                        "Client-side timeout.",
260	                        remotingException);
261	
262	                throw remotingException;
263	            }
264	        } finally {
265	            // just add new valid channel to NettyChannel's cache
266	            if (!isConnected()) {
267	                // future.cancel(true);
268	            }
269	        }
270	    }
