57	import static org.apache.dubbo.common.constants.LoggerCodeConstants.TRANSPORT_FAILED_CLOSE;
58	import static org.apache.dubbo.remoting.Constants.EVENT_LOOP_BOSS_POOL_NAME;
59	import static org.apache.dubbo.remoting.Constants.EVENT_LOOP_WORKER_POOL_NAME;
60	
61	/**
62	 * NettyServer.
63	 */
64	public class NettyServer extends AbstractServer {
65	
66	    /**
67	     * the cache for alive worker channel.
68	     * <ip:port, dubbo channel>
69	     */
70	    private Map<String, Channel> channels;
71	    /**
72	     * netty server bootstrap.
73	     */
74	    private ServerBootstrap bootstrap;
75	    /**
76	     * the boss channel that receive connections and dispatch these to worker channel.
77	     */
78	    private io.netty.channel.Channel channel;
79	
80	    private EventLoopGroup bossGroup;
81	    private EventLoopGroup workerGroup;
82	    private int serverShutdownTimeoutMills;
83	
84	    public NettyServer(URL url, ChannelHandler handler) throws RemotingException {
85	        // you can customize name and type of client thread pool by THREAD_NAME_KEY and THREAD_POOL_KEY in
86	        // CommonConstants.
87	        // the handler will be wrapped: MultiMessageHandler->HeartbeatHandler->handler
88	        super(url, ChannelHandlers.wrap(handler, url));
89	    }
90	
91	    /**
92	     * Init and start netty server
93	     *
94	     * @throws Throwable
95	     */
96	    @Override
97	    protected void doOpen() throws Throwable {
98	        bootstrap = new ServerBootstrap();
99	
100	        // initialize serverShutdownTimeoutMills before potential usage to avoid NPE.
101	        // read config before destroy
102	        serverShutdownTimeoutMills = ConfigurationUtils.getServerShutdownTimeout(getUrl().getOrDefaultModuleModel());
103	
104	        bossGroup = createBossGroup();
105	        workerGroup = createWorkerGroup();
106	
107	        final NettyServerHandler nettyServerHandler = createNettyServerHandler();
108	        channels = nettyServerHandler.getChannels();
109	
110	        initServerBootstrap(nettyServerHandler);
111	
112	        // bind
113	        try {
114	            ChannelFuture channelFuture = bootstrap.bind(getBindAddress());
115	            channelFuture.syncUninterruptibly();
116	            channel = channelFuture.channel();
117	        } catch (Throwable t) {
118	            closeBootstrap();
119	            throw t;
120	        }
121	
122	        // metrics
123	        if (isSupportMetrics()) {
124	            ApplicationModel applicationModel = ApplicationModel.defaultModel();
125	            MetricsEventBus.post(NettyEvent.toNettyEvent(applicationModel), () -> {
126	                Map<String, Long> dataMap = new HashMap<>();
127	                dataMap.put(
128	                        MetricsKey.NETTY_ALLOCATOR_HEAP_MEMORY_USED.getName(),
129	                        PooledByteBufAllocator.DEFAULT.metric().usedHeapMemory());
130	                dataMap.put(
131	                        MetricsKey.NETTY_ALLOCATOR_DIRECT_MEMORY_USED.getName(),
132	                        PooledByteBufAllocator.DEFAULT.metric().usedDirectMemory());
133	                dataMap.put(MetricsKey.NETTY_ALLOCATOR_HEAP_ARENAS_NUM.getName(), (long)
134	                        PooledByteBufAllocator.DEFAULT.numHeapArenas());
135	                dataMap.put(MetricsKey.NETTY_ALLOCATOR_DIRECT_ARENAS_NUM.getName(), (long)
136	                        PooledByteBufAllocator.DEFAULT.numDirectArenas());
137	                dataMap.put(MetricsKey.NETTY_ALLOCATOR_NORMAL_CACHE_SIZE.getName(), (long)
138	                        PooledByteBufAllocator.DEFAULT.normalCacheSize());
139	                dataMap.put(MetricsKey.NETTY_ALLOCATOR_SMALL_CACHE_SIZE.getName(), (long)
140	                        PooledByteBufAllocator.DEFAULT.smallCacheSize());
141	                dataMap.put(MetricsKey.NETTY_ALLOCATOR_THREAD_LOCAL_CACHES_NUM.getName(), (long)
142	                        PooledByteBufAllocator.DEFAULT.numThreadLocalCaches());
143	                dataMap.put(MetricsKey.NETTY_ALLOCATOR_CHUNK_SIZE.getName(), (long)
144	                        PooledByteBufAllocator.DEFAULT.chunkSize());
145	                return dataMap;
146	            });
147	        }
148	    }
149	
150	    private boolean isSupportMetrics() {
151	        return ClassUtils.isPresent("io.netty.buffer.PooledByteBufAllocatorMetric", NettyServer.class.getClassLoader());
152	    }
153	
154	    protected EventLoopGroup createBossGroup() {
155	        return NettyEventLoopFactory.eventLoopGroup(1, EVENT_LOOP_BOSS_POOL_NAME);
156	    }
157	
158	    protected EventLoopGroup createWorkerGroup() {
159	        return NettyEventLoopFactory.eventLoopGroup(
160	                getUrl().getPositiveParameter(IO_THREADS_KEY, Constants.DEFAULT_IO_THREADS),
161	                EVENT_LOOP_WORKER_POOL_NAME);
162	    }
163	
164	    protected NettyServerHandler createNettyServerHandler() {
165	        return new NettyServerHandler(getUrl(), this);
166	    }
167	
168	    protected void initServerBootstrap(NettyServerHandler nettyServerHandler) {
169	        boolean keepalive = getUrl().getParameter(KEEP_ALIVE_KEY, Boolean.FALSE);
170	        bootstrap
171	                .group(bossGroup, workerGroup)
172	                .channel(NettyEventLoopFactory.serverSocketChannelClass())
173	                .option(ChannelOption.SO_REUSEADDR, Boolean.TRUE)
174	                .childOption(ChannelOption.TCP_NODELAY, Boolean.TRUE)
175	                .childOption(ChannelOption.SO_KEEPALIVE, keepalive)
176	                .childOption(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
177	                .childHandler(new ChannelInitializer<SocketChannel>() {
178	                    @Override
179	                    protected void initChannel(SocketChannel ch) throws Exception {
180	                        int closeTimeout = UrlUtils.getCloseTimeout(getUrl());
181	                        NettyCodecAdapter adapter = new NettyCodecAdapter(getCodec(), getUrl(), NettyServer.this);
182	                        ch.pipeline().addLast("negotiation", new SslServerTlsHandler(getUrl()));
183	                        ch.pipeline()
184	                                .addLast("decoder", adapter.getDecoder())
185	                                .addLast("encoder", adapter.getEncoder())
186	                                .addLast("server-idle-handler", new IdleStateHandler(0, 0, closeTimeout, MILLISECONDS))
187	                                .addLast("handler", nettyServerHandler);
188	                    }
189	                });
190	    }
191	
192	    @Override
193	    protected void doClose() {
194	        try {
195	            if (channel != null) {
196	                // unbind.
197	                channel.close();
198	            }
199	        } catch (Throwable e) {
200	            logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
201	        }
202	        try {
203	            Collection<Channel> channels = getChannels();
204	            if (CollectionUtils.isNotEmpty(channels)) {
205	                for (Channel channel : channels) {
206	                    try {
207	                        channel.close();
208	                    } catch (Throwable e) {
209	                        logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
210	                    }
211	                }
212	            }
213	        } catch (Throwable e) {
214	            logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
215	        }
216	        closeBootstrap();
217	        try {
218	            if (channels != null) {
219	                channels.clear();
220	            }
221	        } catch (Throwable e) {
222	            logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
223	        }
224	    }
225	
226	    private void closeBootstrap() {
227	        try {
228	            if (bootstrap != null) {
229	                long timeout = ConfigurationUtils.reCalShutdownTime(serverShutdownTimeoutMills);
230	                long quietPeriod = Math.min(2000L, timeout);
231	                Future<?> bossGroupShutdownFuture = bossGroup.shutdownGracefully(quietPeriod, timeout, MILLISECONDS);
232	                Future<?> workerGroupShutdownFuture =
233	                        workerGroup.shutdownGracefully(quietPeriod, timeout, MILLISECONDS);
234	                bossGroupShutdownFuture.syncUninterruptibly();
235	                workerGroupShutdownFuture.syncUninterruptibly();
236	            }
237	        } catch (Throwable e) {
238	            logger.warn(TRANSPORT_FAILED_CLOSE, "", "", e.getMessage(), e);
239	        }
240	    }
241	
242	    @Override
243	    protected int getChannelsSize() {
244	        return channels.size();
245	    }
246	
247	    @Override
248	    public Collection<Channel> getChannels() {
249	        return new ArrayList<>(channels.values());
250	    }
251	
252	    @Override
253	    public Channel getChannel(InetSocketAddress remoteAddress) {
254	        return channels.get(NetUtils.toAddressString(remoteAddress));
255	    }
256	
257	    @Override
258	    public boolean canHandleIdle() {
259	        return true;
260	    }
261	
262	    @Override
263	    public boolean isBound() {
264	        return channel.isActive();
265	    }
266	
267	    protected EventLoopGroup getBossGroup() {
268	        return bossGroup;
269	    }
270	
271	    protected EventLoopGroup getWorkerGroup() {
272	        return workerGroup;
273	    }
274	
275	    protected ServerBootstrap getServerBootstrap() {
276	        return bootstrap;
277	    }
278	
279	    protected io.netty.channel.Channel getBossChannel() {
280	        return channel;
281	    }
282	
283	    protected Map<String, Channel> getServerChannels() {
284	        return channels;
285	    }
286	
287	    @Override
288	    public void fireChannelEvent(ChannelEvent event) {
289	        Collection<Channel> channels = getChannels();
290	        if (CollectionUtils.isEmpty(channels)) {
291	            return;
292	        }
293	        for (Channel channel : channels) {
294	            try {
295	                if (channel.isConnected()) {
296	                    fireChannelEventToChannel(channel, event);
297	                }
298	            } catch (Throwable e) {
299	                logger.warn(
300	                        TRANSPORT_FAILED_CLOSE,
301	                        "",
302	                        "",
303	                        "Failed to fire channel event to channel: " + channel + ", event: " + event,
304	                        e);
305	            }
306	        }
307	    }
308	
309	    /**
310	     * Fire ChannelEvent to the channel.
311	     * The event will be handled by protocol-specific handlers.
312	     *
313	     * @param channel the Dubbo channel
314	     * @param event the channel event to fire
315	     */
316	    private void fireChannelEventToChannel(Channel channel, ChannelEvent event) {
317	        if (channel instanceof NettyChannel) {
318	            io.netty.channel.Channel nettyChannel = ((NettyChannel) channel).getNioChannel();
319	            if (nettyChannel != null && nettyChannel.isActive()) {
320	                nettyChannel.pipeline().fireUserEventTriggered(event);
321	            }
322	        }
323	    }
324	}
