61	public class DubboCodec extends ExchangeCodec {
62	
63	    public static final String NAME = "dubbo";
64	    public static final String DUBBO_VERSION = Version.getProtocolVersion();
65	    public static final byte RESPONSE_WITH_EXCEPTION = 0;
66	    public static final byte RESPONSE_VALUE = 1;
67	    public static final byte RESPONSE_NULL_VALUE = 2;
68	    public static final byte RESPONSE_WITH_EXCEPTION_WITH_ATTACHMENTS = 3;
69	    public static final byte RESPONSE_VALUE_WITH_ATTACHMENTS = 4;
70	    public static final byte RESPONSE_NULL_VALUE_WITH_ATTACHMENTS = 5;
71	    public static final Object[] EMPTY_OBJECT_ARRAY = new Object[0];
72	    public static final Class<?>[] EMPTY_CLASS_ARRAY = new Class<?>[0];
73	    private static final ErrorTypeAwareLogger log = LoggerFactory.getErrorTypeAwareLogger(DubboCodec.class);
74	
75	    private static final AtomicBoolean decodeInUserThreadLogged = new AtomicBoolean(false);
76	    private final CallbackServiceCodec callbackServiceCodec;
77	    private final FrameworkModel frameworkModel;
78	    private final ByteAccessor customByteAccessor;
79	    private static final String DECODE_IN_IO_THREAD_KEY = "decode.in.io.thread";
80	
81	    public DubboCodec(FrameworkModel frameworkModel) {
82	        this.frameworkModel = frameworkModel;
83	        callbackServiceCodec = new CallbackServiceCodec(frameworkModel);
84	        customByteAccessor = Optional.ofNullable(SystemPropertyConfigUtils.getSystemProperty(SYSTEM_BYTE_ACCESSOR_KEY))
85	                .filter(StringUtils::isNotBlank)
86	                .map(key ->
87	                        frameworkModel.getExtensionLoader(ByteAccessor.class).getExtension(key))
88	                .orElse(null);
89	    }
