91	    @Override
92	    protected Object decodeBody(Channel channel, InputStream is, byte[] header) throws IOException {
93	        byte flag = header[2], proto = (byte) (flag & SERIALIZATION_MASK);
94	        // get request id.
95	        long id = Bytes.bytes2long(header, 4);
96	        if ((flag & FLAG_REQUEST) == 0) {
97	            // decode response.
98	            Response res = new Response(id);
99	            if ((flag & FLAG_EVENT) != 0) {
100	                res.setEvent(true);
101	            }
102	            // get status.
103	            byte status = header[3];
104	            res.setStatus(status);
105	            try {
106	                if (status == Response.OK) {
107	                    Object data;
108	                    if (res.isEvent()) {
109	                        byte[] eventPayload = CodecSupport.getPayload(is);
110	                        if (CodecSupport.isHeartBeat(eventPayload, proto)) {
111	                            // heart beat response data is always null;
112	                            data = null;
113	                        } else {
114	                            ObjectInput in = CodecSupport.deserialize(
115	                                    channel.getUrl(), new ByteArrayInputStream(eventPayload), proto);
116	                            data = decodeEventData(channel, in, eventPayload);
117	                        }
118	                    } else {
119	                        DecodeableRpcResult result;
120	                        Invocation inv = (Invocation) getRequestData(channel, res, id);
121	                        if (channel.getUrl().getParameter(DECODE_IN_IO_THREAD_KEY, DEFAULT_DECODE_IN_IO_THREAD)) {
122	                            if (customByteAccessor != null) {
123	                                result = customByteAccessor.getRpcResult(
124	                                        channel, res, new UnsafeByteArrayInputStream(readMessageData(is)), inv, proto);
125	                            } else {
126	                                result = new DecodeableRpcResult(
127	                                        channel, res, new UnsafeByteArrayInputStream(readMessageData(is)), inv, proto);
128	                            }
129	                            result.decode();
130	                        } else {
131	                            if (customByteAccessor != null) {
132	                                result = customByteAccessor.getRpcResult(
133	                                        channel, res, new UnsafeByteArrayInputStream(readMessageData(is)), inv, proto);
134	                            } else {
135	                                result = new DecodeableRpcResult(
136	                                        channel, res, new UnsafeByteArrayInputStream(readMessageData(is)), inv, proto);
137	                            }
138	                        }
139	                        data = result;
140	                    }
141	                    res.setResult(data);
142	                } else {
143	                    ObjectInput in = CodecSupport.deserialize(channel.getUrl(), is, proto);
144	                    res.setErrorMessage(in.readUTF());
145	                }
146	            } catch (Throwable t) {
147	                if (log.isWarnEnabled()) {
148	                    log.warn(PROTOCOL_FAILED_DECODE, "", "", "Decode response failed: " + t.getMessage(), t);
149	                }
150	                res.setStatus(Response.CLIENT_ERROR);
151	                res.setErrorMessage(StringUtils.toString(t));
152	            }
153	            return res;
154	        } else {
155	            // decode request.
156	            Request req;
157	            try {
158	                Object data;
159	                if ((flag & FLAG_EVENT) != 0) {
160	                    byte[] eventPayload = CodecSupport.getPayload(is);
161	                    if (CodecSupport.isHeartBeat(eventPayload, proto)) {
162	                        // heart beat response data is always null;
163	                        req = new HeartBeatRequest(id);
164	                        req.setVersion(Version.getProtocolVersion());
165	                        req.setTwoWay((flag & FLAG_TWOWAY) != 0);
166	                        ((HeartBeatRequest) req).setProto(proto);
167	                        data = null;
168	                    } else {
169	                        req = new Request(id);
170	                        req.setVersion(Version.getProtocolVersion());
171	                        req.setTwoWay((flag & FLAG_TWOWAY) != 0);
172	
173	                        ObjectInput in = CodecSupport.deserialize(
174	                                channel.getUrl(), new ByteArrayInputStream(eventPayload), proto);
175	                        data = decodeEventData(channel, in, eventPayload);
176	                    }
177	                    req.setEvent(true);
178	                } else {
179	                    req = new Request(id);
180	                    req.setVersion(Version.getProtocolVersion());
181	                    req.setTwoWay((flag & FLAG_TWOWAY) != 0);
182	
183	                    // get data length.
184	                    int len = Bytes.bytes2int(header, 12);
185	                    req.setPayload(len);
186	
187	                    DecodeableRpcInvocation inv;
188	                    if (isDecodeDataInIoThread(channel)) {
189	                        if (customByteAccessor != null) {
190	                            inv = customByteAccessor.getRpcInvocation(
191	                                    channel, req, new UnsafeByteArrayInputStream(readMessageData(is)), proto);
192	                        } else {
193	                            inv = new DecodeableRpcInvocation(
194	                                    frameworkModel,
195	                                    channel,
196	                                    req,
197	                                    new UnsafeByteArrayInputStream(readMessageData(is)),
198	                                    proto);
199	                        }
200	                        inv.decode();
201	                    } else {
202	                        if (customByteAccessor != null) {
203	                            inv = customByteAccessor.getRpcInvocation(
204	                                    channel, req, new UnsafeByteArrayInputStream(readMessageData(is)), proto);
205	                        } else {
206	                            inv = new DecodeableRpcInvocation(
207	                                    frameworkModel,
208	                                    channel,
209	                                    req,
210	                                    new UnsafeByteArrayInputStream(readMessageData(is)),
211	                                    proto);
212	                        }
213	                    }
214	                    data = inv;
215	                }
216	                req.setData(data);
217	            } catch (Throwable t) {
218	                if (log.isWarnEnabled()) {
219	                    log.warn(PROTOCOL_FAILED_DECODE, "", "", "Decode request failed: " + t.getMessage(), t);
220	                }
221	                // bad request
222	                req = new HeartBeatRequest(id);
223	                req.setBroken(true);
224	                req.setData(t);
225	            }
226	
227	            return req;
228	        }
229	    }
