231	    private boolean isDecodeDataInIoThread(Channel channel) {
232	        Object obj = channel.getAttribute(DECODE_IN_IO_THREAD_KEY);
233	        if (obj instanceof Boolean) {
234	            return (Boolean) obj;
235	        }
236	
237	        String mode = ExecutorRepository.getMode(channel.getUrl().getOrDefaultApplicationModel());
238	        boolean isIsolated = EXECUTOR_MANAGEMENT_MODE_ISOLATION.equals(mode);
239	
240	        if (isIsolated && !decodeInUserThreadLogged.compareAndSet(false, true)) {
241	            channel.setAttribute(DECODE_IN_IO_THREAD_KEY, true);
242	            return true;
243	        }
244	
245	        boolean decodeDataInIoThread =
246	                channel.getUrl().getParameter(DECODE_IN_IO_THREAD_KEY, DEFAULT_DECODE_IN_IO_THREAD);
247	        if (isIsolated && !decodeDataInIoThread) {
248	            log.info("Because thread pool isolation is enabled on the dubbo protocol, the body can only be decoded "
249	                    + "on the io thread, and the parameter[" + DECODE_IN_IO_THREAD_KEY + "] will be ignored");
250	            // Why? because obtaining the isolated thread pool requires the serviceKey of the service,
251	            // and this part must be decoded before it can be obtained (more see DubboExecutorSupport)
252	            channel.setAttribute(DECODE_IN_IO_THREAD_KEY, true);
253	            return true;
254	        }
255	        channel.setAttribute(DECODE_IN_IO_THREAD_KEY, decodeDataInIoThread);
256	        return decodeDataInIoThread;
257	    }
