259	    private byte[] readMessageData(InputStream is) throws IOException {
260	        if (is.available() > 0) {
261	            byte[] result = new byte[is.available()];
262	            is.read(result);
263	            return result;
264	        }
265	        return new byte[] {};
266	    }
