278	    @Override
279	    protected void encodeRequestData(Channel channel, ObjectOutput out, Object data, String version)
280	            throws IOException {
281	        RpcInvocation inv = (RpcInvocation) data;
282	
283	        out.writeUTF(version);
284	        // https://github.com/apache/dubbo/issues/6138
285	        String serviceName = inv.getAttachment(INTERFACE_KEY);
286	        if (serviceName == null) {
287	            serviceName = inv.getAttachment(PATH_KEY);
288	        }
289	        out.writeUTF(serviceName);
290	        out.writeUTF(inv.getAttachment(VERSION_KEY));
291	
292	        out.writeUTF(inv.getMethodName());
293	        out.writeUTF(inv.getParameterTypesDesc());
294	        Object[] args = inv.getArguments();
295	        if (args != null) {
296	            for (int i = 0; i < args.length; i++) {
297	                out.writeObject(callbackServiceCodec.encodeInvocationArgument(channel, inv, i));
298	            }
299	        }
300	        out.writeAttachments(inv.getObjectAttachments());
301	    }
302	
303	    @Override
304	    protected void encodeResponseData(Channel channel, ObjectOutput out, Object data, String version)
305	            throws IOException {
306	        Result result = (Result) data;
307	        // currently, the version value in Response records the version of Request
308	        boolean attach = Version.isSupportResponseAttachment(version);
309	        Throwable th = result.getException();
310	        if (th == null) {
311	            Object ret = result.getValue();
312	            if (ret == null) {
313	                out.writeByte(attach ? RESPONSE_NULL_VALUE_WITH_ATTACHMENTS : RESPONSE_NULL_VALUE);
314	            } else {
315	                out.writeByte(attach ? RESPONSE_VALUE_WITH_ATTACHMENTS : RESPONSE_VALUE);
316	                out.writeObject(ret);
317	            }
318	        } else {
319	            out.writeByte(attach ? RESPONSE_WITH_EXCEPTION_WITH_ATTACHMENTS : RESPONSE_WITH_EXCEPTION);
320	            out.writeThrowable(th);
321	        }
322	
323	        if (attach) {
324	            // returns current version of Response to consumer side.
325	            result.getObjectAttachments().put(DUBBO_VERSION_KEY, Version.getProtocolVersion());
326	            out.writeAttachments(result.getObjectAttachments());
327	        }
328	    }
