330	    @Override
331	    protected Serialization getSerialization(Channel channel, Request req) {
332	        if (!(req.getData() instanceof Invocation)) {
333	            return super.getSerialization(channel, req);
334	        }
335	        return DubboCodecSupport.getRequestSerialization(channel.getUrl(), (Invocation) req.getData());
336	    }
337	
338	    @Override
339	    protected Serialization getSerialization(Channel channel, Response res) {
340	        if (res instanceof HeartBeatResponse) {
341	            return CodecSupport.getSerializationById(((HeartBeatResponse) res).getProto());
342	        }
343	        if (!(res.getResult() instanceof AppResponse)) {
344	            return super.getSerialization(channel, res);
345	        }
346	        return DubboCodecSupport.getResponseSerialization(channel.getUrl(), (AppResponse) res.getResult());
347	    }
