40	public class NettyHandler extends SimpleChannelHandler {
41	
42	    private static final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(NettyHandler.class);
43	
44	    private final Map<String, Channel> channels = new ConcurrentHashMap<>(); // <ip:port, channel>
45	
46	    private final URL url;
47	
48	    private final ChannelHandler handler;
49	
50	    public NettyHandler(URL url, ChannelHandler handler) {
51	        if (url == null) {
52	            throw new IllegalArgumentException("url == null");
53	        }
54	        if (handler == null) {
55	            throw new IllegalArgumentException("handler == null");
56	        }
57	        this.url = url;
58	        this.handler = handler;
59	    }
60	
61	    public Map<String, Channel> getChannels() {
62	        return channels;
63	    }
64	
65	    @Override
66	    public void channelConnected(ChannelHandlerContext ctx, ChannelStateEvent e) throws Exception {
67	        org.jboss.netty.channel.Channel ch = ctx.getChannel();
68	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
69	        try {
70	            if (channel != null) {
71	                channels.put(NetUtils.toAddressString((InetSocketAddress) ch.getRemoteAddress()), channel);
72	            }
73	            handler.connected(channel);
74	        } finally {
75	            NettyChannel.removeChannelIfDisconnected(ch);
76	        }
77	
78	        if (logger.isInfoEnabled() && channel != null) {
79	            logger.info(
80	                    "The connection {} between {} and {} is established.",
81	                    ch,
82	                    channel.getRemoteAddress(),
83	                    channel.getLocalAddress());
84	        }
85	    }
86	
87	    @Override
88	    public void channelDisconnected(ChannelHandlerContext ctx, ChannelStateEvent e) throws Exception {
89	        org.jboss.netty.channel.Channel ch = ctx.getChannel();
90	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
91	        try {
92	            channels.remove(NetUtils.toAddressString((InetSocketAddress) ch.getRemoteAddress()));
93	            handler.disconnected(channel);
94	        } finally {
95	            NettyChannel.removeChannelIfDisconnected(ch);
96	        }
97	
98	        if (logger.isInfoEnabled()) {
99	            logger.info(
100	                    "The connection {} between {} and {} is disconnected.",
101	                    ch,
102	                    channel.getRemoteAddress(),
103	                    channel.getLocalAddress());
104	        }
105	    }
106	
107	    @Override
108	    public void messageReceived(ChannelHandlerContext ctx, MessageEvent e) throws Exception {
109	        NettyChannel channel = NettyChannel.getOrAddChannel(ctx.getChannel(), url, handler);
110	        try {
111	            handler.received(channel, e.getMessage());
112	        } finally {
113	            NettyChannel.removeChannelIfDisconnected(ctx.getChannel());
114	        }
115	    }
116	
117	    @Override
118	    public void writeRequested(ChannelHandlerContext ctx, MessageEvent e) throws Exception {
119	        super.writeRequested(ctx, e);
120	        NettyChannel channel = NettyChannel.getOrAddChannel(ctx.getChannel(), url, handler);
121	        try {
122	            handler.sent(channel, e.getMessage());
123	        } finally {
124	            NettyChannel.removeChannelIfDisconnected(ctx.getChannel());
125	        }
126	    }
127	
128	    @Override
129	    public void exceptionCaught(ChannelHandlerContext ctx, ExceptionEvent e) throws Exception {
130	        org.jboss.netty.channel.Channel ch = ctx.getChannel();
131	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
132	        try {
133	            handler.caught(channel, e.getCause());
134	        } finally {
135	            NettyChannel.removeChannelIfDisconnected(ch);
136	        }
137	
138	        if (logger.isWarnEnabled()) {
139	            logger.warn(
140	                    TRANSPORT_UNEXPECTED_EXCEPTION,
141	                    "",
142	                    "",
143	                    channel == null
144	                            ? String.format("The connection %s has exception.", ch)
145	                            : String.format(
146	                                    "The connection %s between %s and %s has exception.",
147	                                    ch, channel.getRemoteAddress(), channel.getLocalAddress()),
148	                    e.getCause());
149	        }
150	    }
151	}
