73	                || configuratorUrl.getHost() == null
74	                || url == null
75	                || url.getHost() == null) {
76	            logger.info("Cannot apply configurator rule, the rule is disabled or is invalid: \n" + configuratorUrl);
77	            return url;
78	        }
79	
80	        String apiVersion = configuratorUrl.getParameter(CONFIG_VERSION_KEY);
81	        if (StringUtils.isNotEmpty(apiVersion)) { // v2.7 or above
82	            String currentSide = url.getSide();
83	            String configuratorSide = configuratorUrl.getSide();
84	            if (currentSide.equals(configuratorSide) && CONSUMER.equals(configuratorSide)) {
85	                url = configureIfMatch(NetUtils.getLocalHost(), url);
86	            } else if (currentSide.equals(configuratorSide) && PROVIDER.equals(configuratorSide)) {
87	                url = configureIfMatch(url.getHost(), url);
88	            }
89	        }
90	        /*
91	         * This else branch is deprecated and is left only to keep compatibility with versions before 2.7.0
92	         */
93	        else {
94	            url = configureDeprecated(url);
95	        }
96	        return url;
97	    }
98	
99	    @Deprecated
100	    private URL configureDeprecated(URL url) {
101	        // If override url has port, means it is a provider address. We want to control a specific provider with this
102	        // override url, it may take effect on the specific provider instance or on consumers holding this provider
103	        // instance.
104	        if (configuratorUrl.getPort() != 0) {
105	            if (url.getPort() == configuratorUrl.getPort()) {
106	                return configureIfMatch(url.getHost(), url);
107	            }
108	        } else {
109	            /*
110	             *  override url don't have a port, means the ip override url specify is a consumer address or 0.0.0.0.
111	             *  1.If it is a consumer ip address, the intention is to control a specific consumer instance, it must takes effect at the consumer side, any provider received this override url should ignore.
112	             *  2.If the ip is 0.0.0.0, this override url can be used on consumer, and also can be used on provider.
113	             */
114	            if (url.getSide(PROVIDER).equals(CONSUMER)) {
115	                // NetUtils.getLocalHost is the ip address consumer registered to registry.
116	                return configureIfMatch(NetUtils.getLocalHost(), url);
117	            } else if (url.getSide(CONSUMER).equals(PROVIDER)) {
118	                // take effect on all providers, so address must be 0.0.0.0, otherwise it won't flow to this if branch
119	                return configureIfMatch(ANYHOST_VALUE, url);
120	            }
121	        }
122	        return url;
123	    }
124	
125	    private URL configureIfMatch(String host, URL url) {
126	        if (ANYHOST_VALUE.equals(configuratorUrl.getHost()) || host.equals(configuratorUrl.getHost())) {
127	            if (isV27ConditionMatchOrUnset(url)) {
128	                Set<String> conditionKeys = genConditionKeys();
129	                String apiVersion = configuratorUrl.getParameter(CONFIG_VERSION_KEY);
130	                if (apiVersion != null && apiVersion.startsWith(RULE_VERSION_V30)) {
131	                    ConditionMatch matcher = (ConditionMatch) configuratorUrl.getAttribute(MATCH_CONDITION);
132	                    if (matcher != null) {
133	                        if (matcher.isMatch(host, url)) {
134	                            return doConfigure(url, configuratorUrl.removeParameters(conditionKeys));
135	                        } else {
136	                            logger.debug("Cannot apply configurator rule, param mismatch, current params are " + url
137	                                    + ", params in rule is " + matcher);
138	                        }
139	                    } else {
140	                        return doConfigure(url, configuratorUrl.removeParameters(conditionKeys));
141	                    }
142	                } else if (isDeprecatedConditionMatch(conditionKeys, url)) {
143	                    return doConfigure(url, configuratorUrl.removeParameters(conditionKeys));
144	                }
145	            }
146	        } else {
147	            logger.debug("Cannot apply configurator rule, host mismatch, current host is " + host + ", host in rule is "
148	                    + configuratorUrl.getHost());
149	        }
150	        return url;
151	    }
152	
153	    /**
154	     * Check if v2.7 configurator rule is set and can be matched.
155	     *
156	     * @param url the configurator rule url
157	     * @return true if v2.7 configurator rule is not set or the rule can be matched.
158	     */
159	    private boolean isV27ConditionMatchOrUnset(URL url) {
160	        String providers = configuratorUrl.getParameter(OVERRIDE_PROVIDERS_KEY);
161	        if (StringUtils.isNotEmpty(providers)) {
162	            boolean match = false;
163	            String[] providerAddresses = providers.split(CommonConstants.COMMA_SEPARATOR);
164	            for (String address : providerAddresses) {
165	                if (address.equals(url.getAddress())
166	                        || address.equals(ANYHOST_VALUE)
167	                        || address.equals(ANYHOST_VALUE + CommonConstants.GROUP_CHAR_SEPARATOR + ANY_VALUE)
168	                        || address.equals(ANYHOST_VALUE + CommonConstants.GROUP_CHAR_SEPARATOR + url.getPort())
169	                        || address.equals(url.getHost())) {
170	                    match = true;
171	                }
172	            }
173	            if (!match) {
174	                logger.debug("Cannot apply configurator rule, provider address mismatch, current address "
175	                        + url.getAddress() + ", address in rule is " + providers);
176	                return false;
177	            }
178	        }
179	
180	        String configApplication = configuratorUrl.getApplication(configuratorUrl.getUsername());
181	        String currentApplication = url.getApplication(url.getUsername());
182	        if (configApplication != null
183	                && !ANY_VALUE.equals(configApplication)
184	                && !configApplication.equals(currentApplication)) {
185	            logger.debug("Cannot apply configurator rule, application name mismatch, current application is "
186	                    + currentApplication + ", application in rule is " + configApplication);
187	            return false;
188	        }
189	
190	        String configServiceKey = configuratorUrl.getServiceKey();
191	        String currentServiceKey = url.getServiceKey();
192	        if (!ANY_VALUE.equals(configServiceKey) && !configServiceKey.equals(currentServiceKey)) {
193	            logger.debug("Cannot apply configurator rule, service mismatch, current service is " + currentServiceKey
194	                    + ", service in rule is " + configServiceKey);
195	            return false;
196	        }
197	
198	        return true;
199	    }
200	
201	    private boolean isDeprecatedConditionMatch(Set<String> conditionKeys, URL url) {
202	        boolean result = true;
203	        for (Map.Entry<String, String> entry : configuratorUrl.getParameters().entrySet()) {
204	            String key = entry.getKey();
205	            String value = entry.getValue();
206	            boolean startWithTilde = startWithTilde(key);
207	            if (startWithTilde || APPLICATION_KEY.equals(key) || SIDE_KEY.equals(key)) {
208	                if (startWithTilde) {
209	                    conditionKeys.add(key);
210	                }
211	                if (value != null
212	                        && !ANY_VALUE.equals(value)
213	                        && !value.equals(url.getParameter(startWithTilde ? key.substring(1) : key))) {
214	                    result = false;
215	                    break;
216	                }
217	            }
218	        }
219	        return result;
220	    }
221	
222	    private Set<String> genConditionKeys() {
223	        Set<String> conditionKeys = new HashSet<>();
224	        conditionKeys.add(CATEGORY_KEY);
225	        conditionKeys.add(Constants.CHECK_KEY);
226	        conditionKeys.add(DYNAMIC_KEY);
227	        conditionKeys.add(ENABLED_KEY);
228	        conditionKeys.add(GROUP_KEY);
229	        conditionKeys.add(VERSION_KEY);
230	        conditionKeys.add(APPLICATION_KEY);
231	        conditionKeys.add(SIDE_KEY);
232	        conditionKeys.add(CONFIG_VERSION_KEY);
233	        conditionKeys.add(COMPATIBLE_CONFIG_KEY);
234	        conditionKeys.add(INTERFACES);
235	        return conditionKeys;
236	    }
237	
238	    private boolean startWithTilde(String key) {
239	        return StringUtils.isNotEmpty(key) && key.startsWith(TILDE);
240	    }
241	
242	    protected abstract URL doConfigure(URL currentUrl, URL configUrl);
243	}
