65	    @Override
66	    public void channelConnected(ChannelHandlerContext ctx, ChannelStateEvent e) throws Exception {
67	        org.jboss.netty.channel.Channel ch = ctx.getChannel();
68	        NettyChannel channel = NettyChannel.getOrAddChannel(ch, url, handler);
69	        try {
70	            if (channel != null) {
71	                channels.put(NetUtils.toAddressString((InetSocketAddress) ch.getRemoteAddress()), channel);
72	            }
73	            handler.connected(channel);
74	        } finally {
75	            NettyChannel.removeChannelIfDisconnected(ch);
76	        }
77	
78	        if (logger.isInfoEnabled() && channel != null) {
79	            logger.info(
80	                    "The connection {} between {} and {} is established.",
81	                    ch,
82	                    channel.getRemoteAddress(),
83	                    channel.getLocalAddress());
84	        }
85	    }
