27	public abstract class AbstractTimerTask implements TimerTask {
28	
29	    private final ChannelProvider channelProvider;
30	    private final HashedWheelTimer hashedWheelTimer;
31	
32	    private final Long tick;
33	
34	    protected volatile boolean cancel = false;
35	
36	    private volatile Timeout timeout;
37	
38	    AbstractTimerTask(ChannelProvider channelProvider, HashedWheelTimer hashedWheelTimer, Long tick) {
39	        if (channelProvider == null || hashedWheelTimer == null || tick == null) {
40	            throw new IllegalArgumentException();
41	        }
42	        this.channelProvider = channelProvider;
43	        this.hashedWheelTimer = hashedWheelTimer;
44	        this.tick = tick;
45	        // do not start here because inheritor should set additional timeout parameters before doing task.
46	    }
47	
48	    static Long lastRead(Channel channel) {
49	        return (Long) channel.getAttribute(HeartbeatHandler.KEY_READ_TIMESTAMP);
50	    }
51	
52	    static Long lastWrite(Channel channel) {
53	        return (Long) channel.getAttribute(HeartbeatHandler.KEY_WRITE_TIMESTAMP);
54	    }
55	
56	    static Long now() {
57	        return System.currentTimeMillis();
58	    }
59	
60	    protected void start() {
61	        this.timeout = hashedWheelTimer.newTimeout(this, tick, TimeUnit.MILLISECONDS);
62	    }
63	
64	    public synchronized void cancel() {
65	        this.cancel = true;
66	        this.timeout.cancel();
67	    }
68	
69	    private synchronized void reput(Timeout timeout) {
70	        if (timeout == null) {
71	            throw new IllegalArgumentException();
72	        }
73	
74	        if (cancel) {
75	            return;
76	        }
77	
78	        if (hashedWheelTimer.isStop() || timeout.isCancelled()) {
79	            return;
80	        }
81	
82	        this.timeout = hashedWheelTimer.newTimeout(timeout.task(), tick, TimeUnit.MILLISECONDS);
83	    }
84	
85	    @Override
86	    public synchronized void run(Timeout timeout) throws Exception {
87	        Collection<Channel> channels = channelProvider.getChannels();
88	        for (Channel channel : channels) {
89	            if (!channel.isClosed()) {
90	                doTask(channel);
91	            }
92	        }
93	        reput(timeout);
94	    }
95	
96	    protected abstract void doTask(Channel channel);
97	
98	    interface ChannelProvider {
99	        Collection<Channel> getChannels();
100	    }
