40	    }
41	
42	    @Override
43	    protected void doTask(Channel channel) {
44	        try {
45	            Long lastRead = lastRead(channel);
46	            Long lastWrite = lastWrite(channel);
47	            Long now = now();
48	            if ((lastRead != null && now - lastRead > heartbeat)
49	                    || (lastWrite != null && now - lastWrite > heartbeat)) {
50	                Request req = new Request();
51	                req.setVersion(Version.getProtocolVersion());
52	                req.setTwoWay(true);
53	                req.setEvent(HEARTBEAT_EVENT);
54	                channel.send(req);
55	                if (logger.isDebugEnabled()) {
56	                    logger.debug("Send heartbeat to remote channel " + channel.getRemoteAddress()
57	                            + ", cause: The channel has no data-transmission exceeds a heartbeat period: "
58	                            + heartbeat + "ms");
59	                }
60	            }
61	        } catch (Throwable t) {
62	            logger.warn(
63	                    TRANSPORT_FAILED_RESPONSE,
64	                    "",
65	                    "",
66	                    "Exception when heartbeat to remote channel " + channel.getRemoteAddress(),
67	                    t);
68	        }
69	    }
70	}
