24	
25	import static org.apache.dubbo.common.constants.LoggerCodeConstants.INTERNAL_ERROR;
26	import static org.apache.dubbo.common.constants.LoggerCodeConstants.TRANSPORT_FAILED_RECONNECT;
27	
28	public class ReconnectTimerTask extends AbstractTimerTask {
29	
30	    private static final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(ReconnectTimerTask.class);
31	
32	    private final int idleTimeout;
33	
34	    public ReconnectTimerTask(
35	            ChannelProvider channelProvider,
36	            HashedWheelTimer hashedWheelTimer,
37	            Long heartbeatTimeoutTick,
38	            int idleTimeout) {
39	        super(channelProvider, hashedWheelTimer, heartbeatTimeoutTick);
40	        this.idleTimeout = idleTimeout;
41	        start();
42	    }
43	
44	    @Override
45	    protected void doTask(Channel channel) {
46	        try {
47	            Long lastRead = lastRead(channel);
48	            Long now = now();
49	
50	            // Rely on reconnect timer to reconnect when AbstractClient.doConnect fails to init the connection
51	            if (!channel.isConnected()) {
52	                try {
53	                    logger.info("Initial connection to " + channel);
54	                    ((Client) channel).reconnect();
55	                } catch (Exception e) {
56	                    logger.error(TRANSPORT_FAILED_RECONNECT, "", "", "Fail to connect to" + channel, e);
57	                }
58	                // check pong at client
59	            } else if (lastRead != null && now - lastRead > idleTimeout) {
60	                logger.warn(
61	                        TRANSPORT_FAILED_RECONNECT,
62	                        "",
63	                        "",
64	                        "Reconnect to channel " + channel + ", because heartbeat read idle time out: " + idleTimeout
65	                                + "ms");
66	                try {
67	                    ((Client) channel).reconnect();
68	                } catch (Exception e) {
69	                    logger.error(TRANSPORT_FAILED_RECONNECT, "", "", channel + "reconnect failed during idle time.", e);
70	                }
71	            }
72	        } catch (Throwable t) {
73	            logger.warn(
74	                    INTERNAL_ERROR,
75	                    "unknown error in remoting module",
76	                    "",
77	                    "Exception when reconnect to remote channel " + channel.getRemoteAddress(),
78	                    t);
79	        }
80	    }
81	}
