47	public class AppScriptStateRouter<T> extends AbstractStateRouter<T> implements ConfigurationListener {
48	    private static final ErrorTypeAwareLogger logger =
49	            LoggerFactory.getErrorTypeAwareLogger(AppScriptStateRouter.class);
50	    private static final String RULE_SUFFIX = ".script-router";
51	
52	    private ScriptRule scriptRule;
53	    private ScriptStateRouter<T> scriptRouter;
54	    private String application;
55	
56	    public AppScriptStateRouter(URL url) {
57	        super(url);
58	    }
59	
60	    @Override
61	    protected BitList<Invoker<T>> doRoute(
62	            BitList<Invoker<T>> invokers,
63	            URL url,
64	            Invocation invocation,
65	            boolean needToPrintMessage,
66	            Holder<RouterSnapshotNode<T>> routerSnapshotNodeHolder,
67	            Holder<String> messageHolder)
68	            throws RpcException {
69	        if (scriptRouter == null || !scriptRule.isValid() || !scriptRule.isEnabled()) {
70	            if (needToPrintMessage) {
71	                messageHolder.set(
72	                        "Directly return from script router. Reason: Invokers from previous router is empty or script is not enabled. Script rule is: "
73	                                + (scriptRule == null ? "null" : scriptRule.getRawRule()));
74	            }
75	            return invokers;
76	        }
77	
78	        invokers = scriptRouter.route(invokers, url, invocation, needToPrintMessage, routerSnapshotNodeHolder);
79	
80	        if (needToPrintMessage) {
81	            messageHolder.set(messageHolder.get());
82	        }
83	
84	        return invokers;
85	    }
86	
87	    @Override
88	    public synchronized void process(ConfigChangedEvent event) {
89	        if (logger.isDebugEnabled()) {
90	            logger.debug("Notification of script rule change, type is: " + event.getChangeType() + ", raw rule is:\n "
91	                    + event.getContent());
92	        }
93	
94	        try {
95	            if (event.getChangeType().equals(ConfigChangeType.DELETED)) {
96	                this.scriptRule = null;
97	            } else {
98	                this.scriptRule = ScriptRule.parse(event.getContent());
99	                URL scriptUrl = getUrl().addParameter(
100	                                TYPE_KEY,
101	                                isEmpty(scriptRule.getType()) ? DEFAULT_SCRIPT_TYPE_KEY : scriptRule.getType())
102	                        .addParameterAndEncoded(RULE_KEY, scriptRule.getScript())
103	                        .addParameter(FORCE_KEY, scriptRule.isForce())
104	                        .addParameter(RUNTIME_KEY, scriptRule.isRuntime());
105	                scriptRouter = new ScriptStateRouter<>(scriptUrl);
106	            }
107	        } catch (Exception e) {
108	            logger.error(
109	                    CLUSTER_TAG_ROUTE_INVALID,
110	                    "Failed to parse the raw tag router rule",
111	                    "",
112	                    "Failed to parse the raw tag router rule and it will not take effect, please check if the "
113	                            + "rule matches with the template, the raw rule is:\n ",
114	                    e);
115	        }
116	    }
117	
118	    @Override
119	    public void notify(BitList<Invoker<T>> invokers) {
120	        if (CollectionUtils.isEmpty(invokers)) {
121	            return;
122	        }
123	
124	        Invoker<T> invoker = invokers.get(0);
125	        URL url = invoker.getUrl();
126	        String providerApplication = url.getRemoteApplication();
127	
128	        if (isEmpty(providerApplication)) {
129	            logger.error(
130	                    CLUSTER_TAG_ROUTE_EMPTY,
131	                    "tag router get providerApplication is empty",
132	                    "",
133	                    "TagRouter must getConfig from or subscribe to a specific application, but the application "
134	                            + "in this TagRouter is not specified.");
135	            return;
136	        }
137	
138	        synchronized (this) {
139	            if (!providerApplication.equals(application)) {
140	                if (StringUtils.isNotEmpty(application)) {
141	                    this.getRuleRepository().removeListener(application + RULE_SUFFIX, this);
142	                }
143	                String key = providerApplication + RULE_SUFFIX;
144	                this.getRuleRepository().addListener(key, this);
145	                application = providerApplication;
146	                String rawRule = this.getRuleRepository().getRule(key, DynamicConfiguration.DEFAULT_GROUP);
147	                if (StringUtils.isNotEmpty(rawRule)) {
148	                    this.process(new ConfigChangedEvent(key, DynamicConfiguration.DEFAULT_GROUP, rawRule));
149	                }
150	            }
151	        }
152	    }
153	
154	    @Override
155	    public void stop() {
156	        if (StringUtils.isNotEmpty(application)) {
157	            this.getRuleRepository().removeListener(application + RULE_SUFFIX, this);
158	        }
159	    }
160	
161	    // for testing purpose
162	    public void setScriptRule(ScriptRule scriptRule) {
163	        this.scriptRule = scriptRule;
164	    }
165	}
