29	import org.apache.dubbo.rpc.Invoker;
30	import org.apache.dubbo.rpc.Result;
31	import org.apache.dubbo.rpc.RpcContext;
32	import org.apache.dubbo.rpc.RpcException;
33	import org.apache.dubbo.rpc.cluster.Directory;
34	import org.apache.dubbo.rpc.cluster.LoadBalance;
35	import org.apache.dubbo.rpc.support.RpcUtils;
36	
37	import java.util.Collections;
38	import java.util.List;
39	import java.util.concurrent.TimeUnit;
40	
41	import static org.apache.dubbo.common.constants.CommonConstants.DEFAULT_FAILBACK_TIMES;
42	import static org.apache.dubbo.common.constants.CommonConstants.RETRIES_KEY;
43	import static org.apache.dubbo.common.constants.LoggerCodeConstants.CLUSTER_FAILED_INVOKE_SERVICE;
44	import static org.apache.dubbo.common.constants.LoggerCodeConstants.CLUSTER_TIMER_RETRY_FAILED;
45	import static org.apache.dubbo.rpc.cluster.Constants.DEFAULT_FAILBACK_TASKS;
46	import static org.apache.dubbo.rpc.cluster.Constants.FAIL_BACK_TASKS_KEY;
47	
48	/**
49	 * When fails, record failure requests and schedule for retry on a regular interval.
50	 * Especially useful for services of notification.
51	 *
52	 * <a href="http://en.wikipedia.org/wiki/Failback">Failback</a>
53	 */
54	public class FailbackClusterInvoker<T> extends AbstractClusterInvoker<T> {
55	
56	    private static final ErrorTypeAwareLogger logger =
57	            LoggerFactory.getErrorTypeAwareLogger(FailbackClusterInvoker.class);
58	
59	    private static final long RETRY_FAILED_PERIOD = 5;
60	
61	    /**
62	     * Number of retries obtained from the configuration, don't contain the first invoke.
63	     */
64	    private final int retries;
65	
66	    private final int failbackTasks;
67	
68	    private volatile Timer failTimer;
69	
70	    public FailbackClusterInvoker(Directory<T> directory) {
71	        super(directory);
72	
73	        int retriesConfig = getUrl().getParameter(RETRIES_KEY, DEFAULT_FAILBACK_TIMES);
74	        if (retriesConfig < 0) {
75	            retriesConfig = DEFAULT_FAILBACK_TIMES;
76	        }
77	        int failbackTasksConfig = getUrl().getParameter(FAIL_BACK_TASKS_KEY, DEFAULT_FAILBACK_TASKS);
78	        if (failbackTasksConfig <= 0) {
79	            failbackTasksConfig = DEFAULT_FAILBACK_TASKS;
80	        }
81	        retries = retriesConfig;
82	        failbackTasks = failbackTasksConfig;
83	    }
84	
85	    private void addFailed(
86	            LoadBalance loadbalance,
87	            Invocation invocation,
88	            List<Invoker<T>> invokers,
89	            Invoker<T> lastInvoker,
90	            URL consumerUrl) {
91	        if (failTimer == null) {
92	            synchronized (this) {
93	                if (failTimer == null) {
94	                    failTimer = new HashedWheelTimer(
95	                            new NamedThreadFactory("failback-cluster-timer", true),
96	                            1,
97	                            TimeUnit.SECONDS,
98	                            32,
99	                            failbackTasks);
100	                }
101	            }
102	        }
103	        RetryTimerTask retryTimerTask = new RetryTimerTask(
104	                loadbalance, invocation, invokers, lastInvoker, retries, RETRY_FAILED_PERIOD, consumerUrl);
105	        try {
106	            failTimer.newTimeout(retryTimerTask, RETRY_FAILED_PERIOD, TimeUnit.SECONDS);
107	        } catch (Throwable e) {
108	            logger.error(
109	                    CLUSTER_TIMER_RETRY_FAILED,
110	                    "add newTimeout exception",
111	                    "",
112	                    "Failback background works error, invocation->" + invocation + ", exception: " + e.getMessage(),
113	                    e);
114	        }
115	    }
116	
117	    @Override
118	    protected Result doInvoke(Invocation invocation, List<Invoker<T>> invokers, LoadBalance loadbalance)
119	            throws RpcException {
120	        Invoker<T> invoker = null;
121	        URL consumerUrl = RpcContext.getServiceContext().getConsumerUrl();
122	        try {
123	            invoker = select(loadbalance, invocation, invokers, null);
124	            // Asynchronous call method must be used here, because failback will retry in the background.
125	            // Then the serviceContext will be cleared after the call is completed.
126	            return invokeWithContextAsync(invoker, invocation, consumerUrl);
127	        } catch (Throwable e) {
128	            logger.error(
129	                    CLUSTER_FAILED_INVOKE_SERVICE,
130	                    "Failback to invoke method and start to retries",
131	                    "",
132	                    "Failback to invoke method " + RpcUtils.getMethodName(invocation)
133	                            + ", wait for retry in background. Ignored exception: "
134	                            + e.getMessage() + ", ",
135	                    e);
136	            if (retries > 0) {
137	                addFailed(loadbalance, invocation, invokers, invoker, consumerUrl);
138	            }
139	            return AsyncRpcResult.newDefaultAsyncResult(null, null, invocation); // ignore
140	        }
141	    }
142	
143	    @Override
144	    public void destroy() {
145	        super.destroy();
146	        if (failTimer != null) {
147	            failTimer.stop();
148	        }
149	    }
150	
151	    /**
152	     * RetryTimerTask
153	     */
154	    private class RetryTimerTask implements TimerTask {
155	        private final Invocation invocation;
156	        private final LoadBalance loadbalance;
157	        private final List<Invoker<T>> invokers;
158	        private final long tick;
159	        private Invoker<T> lastInvoker;
160	        private URL consumerUrl;
161	
162	        /**
163	         * Number of retries obtained from the configuration, don't contain the first invoke.
164	         */
165	        private final int retries;
166	
167	        /**
168	         * Number of retried.
169	         */
170	        private int retriedTimes = 0;
171	
172	        RetryTimerTask(
173	                LoadBalance loadbalance,
174	                Invocation invocation,
175	                List<Invoker<T>> invokers,
176	                Invoker<T> lastInvoker,
177	                int retries,
178	                long tick,
179	                URL consumerUrl) {
180	            this.loadbalance = loadbalance;
181	            this.invocation = invocation;
182	            this.invokers = invokers;
183	            this.retries = retries;
184	            this.tick = tick;
185	            this.lastInvoker = lastInvoker;
186	            this.consumerUrl = consumerUrl;
187	        }
188	
189	        @Override
190	        public void run(Timeout timeout) {
191	            try {
192	                logger.info("Attempt to retry to invoke method " + RpcUtils.getMethodName(invocation)
193	                        + ". The total will retry " + retries + " times, the current is the " + retriedTimes
194	                        + " retry");
195	                Invoker<T> retryInvoker =
196	                        select(loadbalance, invocation, invokers, Collections.singletonList(lastInvoker));
197	                lastInvoker = retryInvoker;
198	                invokeWithContextAsync(retryInvoker, invocation, consumerUrl);
199	            } catch (Throwable e) {
200	                logger.error(
201	                        CLUSTER_FAILED_INVOKE_SERVICE,
202	                        "Failed retry to invoke method",
203	                        "",
204	                        "Failed retry to invoke method " + RpcUtils.getMethodName(invocation) + ", waiting again.",
205	                        e);
206	                if ((++retriedTimes) >= retries) {
207	                    logger.error(
208	                            CLUSTER_FAILED_INVOKE_SERVICE,
209	                            "Failed retry to invoke method and retry times exceed threshold",
210	                            "",
211	                            "Failed retry times exceed threshold (" + retries + "), We have to abandon, invocation->"
212	                                    + invocation,
213	                            e);
214	                } else {
215	                    rePut(timeout);
216	                }
217	            }
218	        }
219	
220	        private void rePut(Timeout timeout) {
221	            if (timeout == null) {
222	                return;
223	            }
224	
225	            Timer timer = timeout.timer();
226	            if (timer.isStop() || timeout.isCancelled()) {
227	                return;
228	            }
229	
230	            timer.newTimeout(timeout.task(), tick, TimeUnit.SECONDS);
231	        }
232	    }
233	}
