18	
19	import org.apache.dubbo.common.URL;
20	import org.apache.dubbo.common.logger.ErrorTypeAwareLogger;
21	import org.apache.dubbo.common.logger.LoggerFactory;
22	import org.apache.dubbo.rpc.Invoker;
23	import org.apache.dubbo.rpc.RpcException;
24	import org.apache.dubbo.rpc.proxy.jdk.JdkProxyFactory;
25	
26	import java.util.Arrays;
27	
28	import static org.apache.dubbo.common.constants.LoggerCodeConstants.PROXY_FAILED;
29	
30	public abstract class AbstractFallbackJdkProxyFactory extends AbstractProxyFactory {
31	
32	    protected final ErrorTypeAwareLogger logger = LoggerFactory.getErrorTypeAwareLogger(this.getClass());
33	
34	    private final JdkProxyFactory jdkProxyFactory = new JdkProxyFactory();
35	
36	    @Override
37	    public <T> Invoker<T> getInvoker(T proxy, Class<T> type, URL url) throws RpcException {
38	        try {
39	            return doGetInvoker(proxy, type, url);
40	        } catch (Throwable throwable) {
41	            // try fall back to JDK proxy factory
42	            String factoryName = getClass().getSimpleName();
43	            try {
44	                Invoker<T> invoker = jdkProxyFactory.getInvoker(proxy, type, url);
45	                logger.error(
46	                        PROXY_FAILED,
47	                        "",
48	                        "",
49	                        "Failed to generate invoker by " + factoryName + " failed. Fallback to use JDK proxy success. "
50	                                + "Interfaces: " + type,
51	                        throwable);
52	                // log out error
53	                return invoker;
54	            } catch (Throwable fromJdk) {
55	                logger.error(
56	                        PROXY_FAILED,
57	                        "",
58	                        "",
59	                        "Failed to generate invoker by " + factoryName
60	                                + " failed. Fallback to use JDK proxy is also failed. " + "Interfaces: " + type
61	                                + " Javassist Error.",
62	                        throwable);
63	                logger.error(
64	                        PROXY_FAILED,
65	                        "",
66	                        "",
67	                        "Failed to generate invoker by " + factoryName
68	                                + " failed. Fallback to use JDK proxy is also failed. " + "Interfaces: " + type
69	                                + " JDK Error.",
70	                        fromJdk);
71	                throw throwable;
72	            }
73	        }
74	    }
75	
76	    @Override
77	    public <T> T getProxy(Invoker<T> invoker, Class<?>[] interfaces) {
78	        try {
79	            return doGetProxy(invoker, interfaces);
80	        } catch (Throwable throwable) {
81	            // try fall back to JDK proxy factory
82	            String factoryName = getClass().getSimpleName();
83	            try {
84	                T proxy = jdkProxyFactory.getProxy(invoker, interfaces);
85	                logger.error(
86	                        PROXY_FAILED,
87	                        "",
88	                        "",
89	                        "Failed to generate proxy by " + factoryName + " failed. Fallback to use JDK proxy success. "
90	                                + "Interfaces: " + Arrays.toString(interfaces),
91	                        throwable);
92	                return proxy;
93	            } catch (Throwable fromJdk) {
94	                logger.error(
95	                        PROXY_FAILED,
96	                        "",
97	                        "",
98	                        "Failed to generate proxy by " + factoryName
99	                                + " failed. Fallback to use JDK proxy is also failed. " + "Interfaces: "
100	                                + Arrays.toString(interfaces) + " Javassist Error.",
101	                        throwable);
102	                logger.error(
103	                        PROXY_FAILED,
104	                        "",
105	                        "",
106	                        "Failed to generate proxy by " + factoryName
107	                                + " failed. Fallback to use JDK proxy is also failed. " + "Interfaces: "
108	                                + Arrays.toString(interfaces) + " JDK Error.",
109	                        fromJdk);
110	                throw throwable;
111	            }
112	        }
113	    }
114	
115	    protected abstract <T> Invoker<T> doGetInvoker(T proxy, Class<T> type, URL url);
116	
117	    protected abstract <T> T doGetProxy(Invoker<T> invoker, Class<?>[] types);
118	}
