35	    public <T> T getProxy(Invoker<T> invoker, Class<?>[] interfaces) {
36	        return (T) Proxy.newProxyInstance(
37	                invoker.getInterface().getClassLoader(), interfaces, new InvokerInvocationHandler(invoker));
38	    }
