43	            @Override
44	            protected Object doInvoke(T proxy, String methodName, Class<?>[] parameterTypes, Object[] arguments)
45	                    throws Throwable {
46	                Method method = proxy.getClass().getMethod(methodName, parameterTypes);
47	                return method.invoke(proxy, arguments);
48	            }
49	        };
50	    }
