57	/**
58	 * NettyClient.
59	 */
60	public class NettyClient extends AbstractClient {
61	
62	    private static final String SOCKS_PROXY_HOST = "socksProxyHost";
63	
64	    private static final String SOCKS_PROXY_PORT = "socksProxyPort";
65	
66	    private static final String DEFAULT_SOCKS_PROXY_PORT = "1080";
67	
68	    /**
69	     * netty client bootstrap
70	     */
71	    private static final GlobalResourceInitializer<EventLoopGroup> EVENT_LOOP_GROUP = new GlobalResourceInitializer<>(
72	            () -> eventLoopGroup(Constants.DEFAULT_IO_THREADS, "NettyClientWorker"),
73	            EventExecutorGroup::shutdownGracefully);
74	
75	    private Bootstrap bootstrap;
76	
77	    /**
78	     * current channel. Each successful invocation of {@link NettyClient#doConnect()} will
79	     * replace this with new channel and close old channel.
80	     * <b>volatile, please copy reference to use.</b>
81	     */
82	    private volatile Channel channel;
83	
84	    /**
85	     * The constructor of NettyClient.
86	     * It wil init and start netty.
87	     */
88	    public NettyClient(final URL url, final ChannelHandler handler) throws RemotingException {
89	        // you can customize name and type of client thread pool by THREAD_NAME_KEY and THREADPOOL_KEY in
90	        // CommonConstants.
91	        // the handler will be wrapped: MultiMessageHandler->HeartbeatHandler->handler
92	        super(url, wrapChannelHandler(url, handler));
93	    }
94	
95	    /**
96	     * Init bootstrap
97	     *
98	     * @throws Throwable
99	     */
100	    @Override
101	    protected void doOpen() throws Throwable {
102	        final NettyClientHandler nettyClientHandler = createNettyClientHandler();
103	        bootstrap = new Bootstrap();
104	        initBootstrap(nettyClientHandler);
105	    }
106	
107	    protected NettyClientHandler createNettyClientHandler() {
108	        return new NettyClientHandler(getUrl(), this);
109	    }
110	
111	    protected void initBootstrap(NettyClientHandler nettyClientHandler) {
112	        bootstrap
113	                .group(EVENT_LOOP_GROUP.get())
114	                .option(ChannelOption.SO_KEEPALIVE, true)
115	                .option(ChannelOption.TCP_NODELAY, true)
116	                .option(ChannelOption.ALLOCATOR, PooledByteBufAllocator.DEFAULT)
117	                // .option(ChannelOption.CONNECT_TIMEOUT_MILLIS, getTimeout())
118	                .channel(socketChannelClass());
119	
120	        bootstrap.option(ChannelOption.CONNECT_TIMEOUT_MILLIS, Math.max(DEFAULT_CONNECT_TIMEOUT, getConnectTimeout()));
121	        SslContext sslContext = SslContexts.buildClientSslContext(getUrl());
122	        bootstrap.handler(new ChannelInitializer<SocketChannel>() {
123	
124	            @Override
125	            protected void initChannel(SocketChannel ch) throws Exception {
126	                int heartbeatInterval = UrlUtils.getHeartbeat(getUrl());
127	
128	                if (sslContext != null) {
129	                    ch.pipeline().addLast("negotiation", new SslClientTlsHandler(sslContext));
130	                }
131	
132	                NettyCodecAdapter adapter = new NettyCodecAdapter(getCodec(), getUrl(), NettyClient.this);
133	                ch.pipeline() // .addLast("logging",new LoggingHandler(LogLevel.INFO))//for debug
134	                        .addLast("decoder", adapter.getDecoder())
135	                        .addLast("encoder", adapter.getEncoder())
136	                        .addLast("client-idle-handler", new IdleStateHandler(heartbeatInterval, 0, 0, MILLISECONDS))
137	                        .addLast("handler", nettyClientHandler);
138	
139	                String socksProxyHost =
140	                        ConfigurationUtils.getProperty(getUrl().getOrDefaultApplicationModel(), SOCKS_PROXY_HOST);
141	                if (socksProxyHost != null && !isFilteredAddress(getUrl().getHost())) {
142	                    int socksProxyPort = Integer.parseInt(ConfigurationUtils.getProperty(
143	                            getUrl().getOrDefaultApplicationModel(), SOCKS_PROXY_PORT, DEFAULT_SOCKS_PROXY_PORT));
144	                    Socks5ProxyHandler socks5ProxyHandler =
145	                            new Socks5ProxyHandler(new InetSocketAddress(socksProxyHost, socksProxyPort));
146	                    ch.pipeline().addFirst(socks5ProxyHandler);
147	                }
148	            }
149	        });
150	    }
151	
152	    private boolean isFilteredAddress(String host) {
153	        // filter local address
154	        return StringUtils.isEquals(NetUtils.getLocalHost(), host) || NetUtils.isLocalHost(host);
155	    }
156	
157	    @Override
158	    protected void doConnect() throws Throwable {
159	        try {
160	            String ipv6Address = NetUtils.getLocalHostV6();
161	            InetSocketAddress connectAddress;
162	            // first try ipv6 address
163	            if (ipv6Address != null && getUrl().getParameter(CommonConstants.IPV6_KEY) != null) {
164	                connectAddress =
165	                        new InetSocketAddress(getUrl().getParameter(CommonConstants.IPV6_KEY), getUrl().getPort());
166	                try {
167	                    doConnect(connectAddress);
168	                    return;
169	                } catch (Throwable throwable) {
170	                    // ignore
171	                }
172	            }
173	
174	            connectAddress = getConnectAddress();
175	            doConnect(connectAddress);
176	        } finally {
177	            // just add new valid channel to NettyChannel's cache
178	            if (!isConnected()) {
179	                // future.cancel(true);
180	            }
181	        }
182	    }
183	
184	    private void doConnect(InetSocketAddress serverAddress) throws RemotingException {
185	        long start = System.currentTimeMillis();
186	        ChannelFuture future = bootstrap.connect(serverAddress);
187	        try {
188	            boolean ret = future.awaitUninterruptibly(getConnectTimeout(), MILLISECONDS);
189	
190	            if (ret && future.isSuccess()) {
191	                Channel newChannel = future.channel();
192	                try {
193	                    // Close old channel
194	                    // copy reference
195	                    Channel oldChannel = NettyClient.this.channel;
196	                    if (oldChannel != null) {
197	                        try {
198	                            if (logger.isInfoEnabled()) {
199	                                logger.info("Close old netty channel " + oldChannel + " on create new netty channel "
200	                                        + newChannel);
201	                            }
202	                            oldChannel.close();
203	                        } finally {
204	                            NettyChannel.removeChannelIfDisconnected(oldChannel);
205	                        }
206	                    }
207	                } finally {
208	                    if (NettyClient.this.isClosed()) {
209	                        try {
210	                            if (logger.isInfoEnabled()) {
211	                                logger.info("Close new netty channel " + newChannel + ", because the client closed.");
212	                            }
213	                            newChannel.close();
214	                        } finally {
215	                            NettyClient.this.channel = null;
216	                            NettyChannel.removeChannelIfDisconnected(newChannel);
217	                        }
218	                    } else {
219	                        NettyClient.this.channel = newChannel;
220	                    }
221	                }
222	            } else if (future.cause() != null) {
223	
224	                Throwable cause = future.cause();
225	
226	                // 6-1 Failed to connect to provider server by other reason.
227	
228	                RemotingException remotingException = new RemotingException(
229	                        this,
230	                        "client(url: " + getUrl() + ") failed to connect to server " + serverAddress
231	                                + ", error message is:" + cause.getMessage(),
232	                        cause);
233	
234	                logger.error(
235	                        TRANSPORT_FAILED_CONNECT_PROVIDER,
236	                        "network disconnected",
237	                        "",
238	                        "Failed to connect to provider server by other reason.",
239	                        cause);
240	
241	                throw remotingException;
242	
243	            } else {
244	
245	                // 6-2 Client-side timeout
246	
247	                RemotingException remotingException = new RemotingException(
248	                        this,
249	                        "client(url: " + getUrl() + ") failed to connect to server "
250	                                + serverAddress + " client-side timeout "
251	                                + getConnectTimeout() + "ms (elapsed: " + (System.currentTimeMillis() - start)
252	                                + "ms) from netty client "
253	                                + NetUtils.getLocalHost() + " using dubbo version " + Version.getVersion());
254	
255	                logger.error(
256	                        TRANSPORT_CLIENT_CONNECT_TIMEOUT,
257	                        "provider crash",
258	                        "",
259	                        "Client-side timeout.",
260	                        remotingException);
261	
262	                throw remotingException;
263	            }
264	        } finally {
265	            // just add new valid channel to NettyChannel's cache
266	            if (!isConnected()) {
267	                // future.cancel(true);
268	            }
269	        }
270	    }
271	
272	    @Override
273	    protected void doDisConnect() throws Throwable {
274	        try {
275	            NettyChannel.removeChannelIfDisconnected(channel);
276	        } catch (Throwable t) {
277	            logger.warn(TRANSPORT_FAILED_DISCONNECT_PROVIDER, "", "", t.getMessage());
278	        }
279	    }
280	
281	    @Override
282	    protected void doClose() throws Throwable {
283	        // can't shut down nioEventLoopGroup because the method will be invoked when closing one channel but not a
284	        // client,
285	        // but when and how to close the nioEventLoopGroup ?
286	        // nioEventLoopGroup.shutdownGracefully();
287	    }
288	
289	    @Override
290	    protected org.apache.dubbo.remoting.Channel getChannel() {
291	        Channel c = channel;
292	        if (c == null) {
293	            return null;
294	        }
295	        return NettyChannel.getOrAddChannel(c, getUrl(), this);
296	    }
297	
298	    Channel getNettyChannel() {
299	        return channel;
300	    }
301	
302	    @Override
303	    public boolean canHandleIdle() {
304	        return true;
305	    }
306	
307	    protected EventLoopGroup getEventLoopGroup() {
308	        return EVENT_LOOP_GROUP.get();
309	    }
310	
311	    protected Bootstrap getBootstrap() {
312	        return bootstrap;
313	    }
314	}
