55	public class GenericHttp2ServerTransportListener extends AbstractServerTransportListener<Http2Header, Http2InputMessage>
56	        implements Http2TransportListener {
57	
58	    private static final ErrorTypeAwareLogger LOGGER =
59	            LoggerFactory.getErrorTypeAwareLogger(GenericHttp2ServerTransportListener.class);
60	
61	    private final H2StreamChannel h2StreamChannel;
62	    private final StreamingDecoder streamingDecoder;
63	    private Http2ServerChannelObserver responseObserver;
64	    private ServerCallListener serverCallListener;
65	
66	    public GenericHttp2ServerTransportListener(
67	            H2StreamChannel h2StreamChannel, URL url, FrameworkModel frameworkModel) {
68	        super(frameworkModel, url, h2StreamChannel);
69	        this.h2StreamChannel = h2StreamChannel;
70	        streamingDecoder = newStreamingDecoder();
71	        responseObserver = prepareResponseObserver(newResponseObserver(h2StreamChannel));
72	    }
73	
74	    protected StreamingDecoder newStreamingDecoder() {
75	        return new DefaultStreamingDecoder();
76	    }
77	
78	    protected Http2ServerChannelObserver newResponseObserver(H2StreamChannel h2StreamChannel) {
79	        return new Http2UnaryServerChannelObserver(getFrameworkModel(), h2StreamChannel);
80	    }
81	
82	    protected Http2ServerChannelObserver newStreamResponseObserver(H2StreamChannel h2StreamChannel) {
83	        Http2ServerChannelObserver responseObserver =
84	                new Http2SseServerChannelObserver(getFrameworkModel(), h2StreamChannel);
85	        responseObserver.addHeadersCustomizer(
86	                (hs, t) -> hs.set(HttpHeaderNames.CONTENT_TYPE.getKey(), MediaType.TEXT_EVENT_STREAM.getName()));
