88	    }
89	
90	    protected Http2ServerChannelObserver prepareResponseObserver(Http2ServerChannelObserver responseObserver) {
91	        responseObserver.setExceptionCustomizer(getExceptionCustomizer());
92	        RpcInvocationBuildContext context = getContext();
93	        responseObserver.setResponseEncoder(context == null ? JsonCodec.INSTANCE : context.getHttpMessageEncoder());
94	        responseObserver.setCancellationContext(RpcContext.getCancellationContext());
95	        responseObserver.setStreamingDecoder(streamingDecoder);
96	        return responseObserver;
97	    }
98	
99	    @Override
100	    protected HttpMessageListener buildHttpMessageListener() {
101	        RpcInvocationBuildContext context = getContext();
102	        RpcInvocation rpcInvocation = buildRpcInvocation(context);
103	
104	        serverCallListener = startListener(rpcInvocation, context.getMethodDescriptor(), context.getInvoker());
105	        DefaultListeningDecoder listeningDecoder = new DefaultListeningDecoder(
106	                context.getHttpMessageDecoder(), context.getMethodMetadata().getActualRequestTypes());
107	        listeningDecoder.setListener(new Http2StreamingDecodeListener(serverCallListener));
108	        streamingDecoder.setFragmentListener(new DefaultFragmentListener(listeningDecoder));
109	        return new StreamingHttpMessageListener(streamingDecoder);
110	    }
