112	    final class DefaultFragmentListener implements FragmentListener {
113	
114	        private final ListeningDecoder listeningDecoder;
115	
116	        public DefaultFragmentListener(ListeningDecoder listeningDecoder) {
117	            this.listeningDecoder = listeningDecoder;
118	        }
119	
120	        @Override
121	        public void bytesRead(int numBytes) {
122	            try {
123	                getH2StreamChannel().consumeBytes(numBytes);
124	            } catch (Exception e) {
125	                LOGGER.warn(PROTOCOL_FAILED_RESPONSE, "", "", "Failed to consume bytes for flow control", e);
126	            }
127	        }
128	
129	        @Override
130	        public void onFragmentMessage(InputStream rawMessage, int messageLength) {
131	            listeningDecoder.decode(rawMessage);
132	        }
133	
134	        @Override
135	        public void onClose() {
136	            listeningDecoder.close();
137	        }
138	    }
139	
140	    /**
141	     * Get the H2StreamChannel for flow control.
142	     */
143	    protected H2StreamChannel getH2StreamChannel() {
144	        return h2StreamChannel;
145	    }
