147	    private ServerCallListener startListener(
148	            RpcInvocation invocation, MethodDescriptor methodDescriptor, Invoker<?> invoker) {
149	        switch (methodDescriptor.getRpcType()) {
150	            case UNARY:
151	                prepareUnaryServerCall();
152	                return new UnaryServerCallListener(invocation, invoker, responseObserver);
153	            case SERVER_STREAM:
154	                prepareStreamServerCall();
155	                return new ServerStreamServerCallListener(invocation, invoker, responseObserver);
156	            case BI_STREAM:
157	            case CLIENT_STREAM:
158	                prepareStreamServerCall();
159	                return new BiStreamServerCallListener(invocation, invoker, responseObserver);
160	            default:
161	                throw new IllegalStateException("Can not reach here");
162	        }
163	    }
164	
165	    protected void prepareUnaryServerCall() {}
166	
167	    protected void prepareStreamServerCall() {
168	        responseObserver = prepareResponseObserver(newStreamResponseObserver(h2StreamChannel));
169	    }
170	
171	    @Override
172	    protected void initializeAltSvc(URL url) {
173	        if (Http3Exchanger.isEnabled(url)) {
174	            String value = "h3=\":" + url.getParameter(Constants.BIND_PORT_KEY, url.getPort()) + '"';
175	            responseObserver.addHeadersCustomizer((hs, t) -> hs.set(HttpHeaderNames.ALT_SVC.getKey(), value));
176	        }
177	    }
178	
179	    @Override
180	    protected void onMetadataCompletion(Http2Header metadata) {
181	        responseObserver.setResponseEncoder(getContext().getHttpMessageEncoder());
182	        responseObserver.setExecutor(getExecutor());
183	        responseObserver.request(1);
184	        if (metadata.isEndStream()) {
185	            getStreamingDecoder().close();
186	        }
187	    }
188	
189	    @Override
190	    protected void onDataCompletion(Http2InputMessage message) {
191	        if (message.isEndStream()) {
192	            getStreamingDecoder().close();
193	        }
194	    }
195	
196	    @Override
197	    protected void onError(Throwable throwable) {
198	        responseObserver.onError(throwable);
199	    }
200	
201	    @Override
202	    protected void onError(Http2InputMessage message, Throwable throwable) {
203	        try {
204	            message.close();
205	        } catch (Exception e) {
206	            throwable.addSuppressed(e);
207	        }
208	        onError(throwable);
209	    }
210	
211	    @Override
212	    protected void onDataFinally(Http2InputMessage message) {}
213	
214	    @Override
215	    public void cancelByRemote(long errorCode) {
216	        responseObserver.cancel(CancelStreamException.fromRemote(errorCode));
217	        if (serverCallListener != null) {
218	            serverCallListener.onCancel(errorCode);
219	        }
220	    }
221	
222	    protected final StreamingDecoder getStreamingDecoder() {
223	        return streamingDecoder;
224	    }
225	
226	    protected final Http2ServerChannelObserver getResponseObserver() {
227	        return responseObserver;
228	    }
229	
230	    @Override
231	    public void close() {
232	        responseObserver.close();
233	    }
234	
235	    @Override
236	    public void onWritabilityChanged() {
237	        responseObserver.onWritabilityChanged();
238	    }
