250	            serverCallListener.onMessage(message);
251	        }
252	
253	        @Override
254	        public void onClose() {
255	            serverCallListener.onComplete();
256	        }
257	    }
258	
259	    private static final class StreamingHttpMessageListener implements HttpMessageListener {
260	
261	        private final StreamingDecoder streamingDecoder;
262	
263	        StreamingHttpMessageListener(StreamingDecoder streamingDecoder) {
264	            this.streamingDecoder = streamingDecoder;
265	        }
266	
267	        @Override
268	        public void onMessage(InputStream inputStream) {
269	            streamingDecoder.decode(inputStream);
270	        }
271	    }
