27	import org.apache.dubbo.rpc.support.RpcUtils;
28	
29	import static org.apache.dubbo.common.constants.CommonConstants.CONSUMER;
30	import static org.apache.dubbo.common.constants.CommonConstants.TIMEOUT_KEY;
31	import static org.apache.dubbo.rpc.Constants.ACTIVES_KEY;
32	
33	/**
34	 * ActiveLimitFilter restrict the concurrent client invocation for a service or service's method from client side.
35	 * To use active limit filter, configured url with <b>actives</b> and provide valid >0 integer value.
36	 * <pre>
37	 *     e.g. <dubbo:reference id="demoService" check="false" interface="org.apache.dubbo.demo.DemoService" "actives"="2"/>
38	 *      In the above example maximum 2 concurrent invocation is allowed.
39	 *      If there are more than configured (in this example 2) is trying to invoke remote method, then rest of invocation
40	 *      will wait for configured timeout(default is 0 second) before invocation gets kill by dubbo.
41	 * </pre>
42	 *
43	 * @see Filter
44	 */
45	@Activate(group = CONSUMER, value = ACTIVES_KEY)
46	public class ActiveLimitFilter implements Filter, Filter.Listener {
47	
48	    private static final String ACTIVE_LIMIT_FILTER_START_TIME = "active_limit_filter_start_time";
49	
50	    @Override
51	    public Result invoke(Invoker<?> invoker, Invocation invocation) throws RpcException {
52	        URL url = invoker.getUrl();
53	        String methodName = RpcUtils.getMethodName(invocation);
54	        int max = invoker.getUrl().getMethodParameter(methodName, ACTIVES_KEY, 0);
55	        final RpcStatus rpcStatus = RpcStatus.getStatus(invoker.getUrl(), RpcUtils.getMethodName(invocation));
56	        if (!RpcStatus.beginCount(url, methodName, max)) {
57	            long timeout = invoker.getUrl().getMethodParameter(RpcUtils.getMethodName(invocation), TIMEOUT_KEY, 0);
58	            long start = System.currentTimeMillis();
59	            long remain = timeout;
60	            synchronized (rpcStatus) {
61	                while (!RpcStatus.beginCount(url, methodName, max)) {
62	                    try {
63	                        rpcStatus.wait(remain);
64	                    } catch (InterruptedException e) {
65	                        // ignore
66	                    }
67	                    long elapsed = System.currentTimeMillis() - start;
68	                    remain = timeout - elapsed;
69	                    if (remain <= 0) {
70	                        throw new RpcException(
71	                                RpcException.LIMIT_EXCEEDED_EXCEPTION,
72	                                "Waiting concurrent invoke timeout in client-side for service:  "
73	                                        + invoker.getInterface().getName()
74	                                        + ", method: " + RpcUtils.getMethodName(invocation) + ", elapsed: "
75	                                        + elapsed + ", timeout: " + timeout + ". concurrent invokes: "
76	                                        + rpcStatus.getActive()
77	                                        + ". max concurrent invoke limit: " + max);
78	                    }
79	                }
80	            }
81	        }
82	
83	        invocation.put(ACTIVE_LIMIT_FILTER_START_TIME, System.currentTimeMillis());
84	
85	        return invoker.invoke(invocation);
86	    }
87	
88	    @Override
89	    public void onResponse(Result appResponse, Invoker<?> invoker, Invocation invocation) {
90	        String methodName = RpcUtils.getMethodName(invocation);
91	        URL url = invoker.getUrl();
92	        int max = invoker.getUrl().getMethodParameter(methodName, ACTIVES_KEY, 0);
93	
94	        RpcStatus.endCount(url, methodName, getElapsed(invocation), true);
95	        notifyFinish(RpcStatus.getStatus(url, methodName), max);
96	    }
97	
98	    @Override
99	    public void onError(Throwable t, Invoker<?> invoker, Invocation invocation) {
100	        String methodName = RpcUtils.getMethodName(invocation);
101	        URL url = invoker.getUrl();
102	        int max = invoker.getUrl().getMethodParameter(methodName, ACTIVES_KEY, 0);
103	
104	        if (t instanceof RpcException) {
105	            RpcException rpcException = (RpcException) t;
106	            if (rpcException.isLimitExceed()) {
107	                return;
108	            }
109	        }
110	        RpcStatus.endCount(url, methodName, getElapsed(invocation), false);
111	        notifyFinish(RpcStatus.getStatus(url, methodName), max);
112	    }
113	
114	    private long getElapsed(Invocation invocation) {
115	        Object beginTime = invocation.get(ACTIVE_LIMIT_FILTER_START_TIME);
116	        return beginTime != null ? System.currentTimeMillis() - (Long) beginTime : 0;
117	    }
118	
119	    private void notifyFinish(final RpcStatus rpcStatus, int max) {
120	        if (max > 0) {
121	            synchronized (rpcStatus) {
122	                rpcStatus.notifyAll();
123	            }
124	        }
125	    }
126	}
