33	import static org.apache.dubbo.rpc.Constants.EXECUTES_KEY;
34	
35	/**
36	 * The maximum parallel execution request count per method per service for the provider.If the max configured
37	 * <b>executes</b> is set to 10 and if invoke request where it is already 10 then it will throw exception. It
38	 * continues the same behaviour un till it is <10.
39	 */
40	@Activate(group = CommonConstants.PROVIDER, value = EXECUTES_KEY)
41	public class ExecuteLimitFilter implements Filter, Filter.Listener {
42	
43	    private static final String EXECUTE_LIMIT_FILTER_START_TIME = "execute_limit_filter_start_time";
44	
45	    @Override
46	    public Result invoke(Invoker<?> invoker, Invocation invocation) throws RpcException {
47	        URL url = invoker.getUrl();
48	        String methodName = RpcUtils.getMethodName(invocation);
49	        int max = url.getMethodParameter(methodName, EXECUTES_KEY, 0);
50	        if (!RpcStatus.beginCount(url, methodName, max)) {
51	            throw new RpcException(
52	                    RpcException.LIMIT_EXCEEDED_EXCEPTION,
53	                    "Failed to invoke method " + RpcUtils.getMethodName(invocation) + " in provider " + url
54	                            + ", cause: The service using threads greater than <dubbo:service executes=\"" + max
55	                            + "\" /> limited.");
56	        }
57	
58	        invocation.put(EXECUTE_LIMIT_FILTER_START_TIME, System.currentTimeMillis());
59	        try {
60	            return invoker.invoke(invocation);
61	        } catch (Throwable t) {
62	            if (t instanceof RuntimeException) {
63	                throw (RuntimeException) t;
64	            } else {
65	                throw new RpcException("unexpected exception when ExecuteLimitFilter", t);
66	            }
67	        }
68	    }
69	
70	    @Override
71	    public void onResponse(Result appResponse, Invoker<?> invoker, Invocation invocation) {
72	        RpcStatus.endCount(invoker.getUrl(), getRealMethodName(invoker, invocation), getElapsed(invocation), true);
73	    }
74	
75	    @Override
76	    public void onError(Throwable t, Invoker<?> invoker, Invocation invocation) {
77	        if (t instanceof RpcException) {
78	            RpcException rpcException = (RpcException) t;
79	            if (rpcException.isLimitExceed()) {
80	                return;
81	            }
82	        }
83	        RpcStatus.endCount(invoker.getUrl(), getRealMethodName(invoker, invocation), getElapsed(invocation), false);
84	    }
85	
86	    private String getRealMethodName(Invoker<?> invoker, Invocation invocation) {
87	        if ((invocation.getMethodName().equals($INVOKE)
88	                        || invocation.getMethodName().equals($INVOKE_ASYNC))
89	                && invocation.getArguments() != null
90	                && invocation.getArguments().length == 3
91	                && !GenericService.class.isAssignableFrom(invoker.getInterface())) {
92	            return ((String) invocation.getArguments()[0]).trim();
93	        }
94	        return invocation.getMethodName();
95	    }
96	
97	    private long getElapsed(Invocation invocation) {
98	        Object beginTime = invocation.get(EXECUTE_LIMIT_FILTER_START_TIME);
99	        return beginTime != null ? System.currentTimeMillis() - (Long) beginTime : 0;
100	    }
101	}
