static void fireChannelEventToAll(
        Collection<org.apache.dubbo.remoting.Channel> channels,
        ChannelEvent event,
        ErrorTypeAwareLogger log) {
    if (CollectionUtils.isEmpty(channels)) {
        return;
    }
    for (org.apache.dubbo.remoting.Channel dubboChannel : channels) {
        try {
            if (dubboChannel.isConnected() && dubboChannel instanceof NettyChannel) {
                Channel nettyChannel = ((NettyChannel) dubboChannel).getNioChannel();
                if (nettyChannel != null && nettyChannel.isActive()) {
                    nettyChannel.pipeline().fireUserEventTriggered(event);
                }
            }
        } catch (Throwable e) {
            log.warn(
                    TRANSPORT_FAILED_CLOSE,
                    "",
                    "",
                    "Failed to fire channel event to channel: " + dubboChannel + ", event: " + event,
                    e);
        }
    }
}

